window.CERT_DATA=window.CERT_DATA||{};window.CERT_DATA['engineer-2020-1']={"round":"2020-1","cert":"engineer","questions":[{"id":"10586","number":1,"category":"소프트웨어 설계","type":"choice","subject":"검토회의 전에 요구사항 명세서를 미리 배포하여 사전 검토한 후 짧은 검토 회의를 통해 오류를 조기에 검출하는데 목적을 두는 요구 사항 검토 방법은?","choices":[{"n":1,"html":"빌드 검증"},{"n":2,"html":"동료 검토"},{"n":3,"html":"워크 스루"},{"n":4,"html":"개발자 검토"}],"answer":[3],"wiki":[{"title":"정적 테스트","url":"https://itwiki.kr/w/정적 테스트"}],"explain":{"ai":["<p>요구사항 명세서를 미리 배포하여 사전 검토하고 짧은 검토 회의를 통해 오류를 조기에 검출하는 방법은 워크 스루이다. 워크 스루는 요구사항 또는 설계서에 대한 검토를 위해 소규모의 전문가 그룹이 모여서 문서를 함께 검토하고 토의하는 방식이다. 이 방식은 요구사항 명세서의 오류나 결함을 조기에 발견하여 수정할 수 있도록 도와준다. 따라서 정답은 3번 워크 스루이다.</p>"]},"rate":69,"rateN":27906},{"id":"10587","number":2,"category":"소프트웨어 설계","type":"choice","subject":"코드 설계에서 일정한 일련번호를 부여하는 방식의 코드는?","choices":[{"n":1,"html":"연상 코드"},{"n":2,"html":"블록 코드"},{"n":3,"html":"순차 코드"},{"n":4,"html":"표의 숫자 코드"}],"answer":[3],"wiki":[{"title":"코드","url":"https://itwiki.kr/w/코드"}],"explain":{"ai":["<p>코드의 종류에는 연상 코드, 블록 코드, 순차 코드, 표의 숫자 코드 등이 있다. 순차 코드는 일정한 규칙에 따라 일련번호를 부여하는 방식이다. 이 방식은 코드를 생성하고 관리하는 데 용이하며 쉽게 알아볼 수 있다. 순차 코드는 일련번호가 연속적으로 부여되기 때문에 코드의 중복이나 오류를 줄일 수 있다. 또한 코드를 생성할 때 특별한 규칙이나 표가 필요하지 않아 간단하게 관리할 수 있다. 따라서 코드 설계에서 일정한 일련번호를 부여하는 방식의 코드는 순차 코드이다.</p>"]},"rate":76,"rateN":24015},{"id":"10588","number":3,"category":"소프트웨어 설계","type":"choice","subject":"객체지향 프로그램에서 데이터를 추상화하는 단위는?","choices":[{"n":1,"html":"메소드"},{"n":2,"html":"클래스"},{"n":3,"html":"상속성"},{"n":4,"html":"메시지"}],"answer":[2],"wiki":[{"title":"객체지향 기법","url":"https://itwiki.kr/w/객체지향 기법"}],"explain":{"ai":["<p>객체지향 프로그램에서 데이터를 추상화하는 단위는 클래스야. 클래스는 객체지향 프로그램에서 데이터와 그 데이터를 조작하는 함수들을 하나의 단위로 묶은거지. 클래스는 객체를 생성하기 위한 모판이나 설계도 같은 개념이야. 클래스를 사용하면 코드를 재사용하기 쉽고 유지 보수가 쉬워지기 때문에 객체지향 프로그램에서 매우 중요해. </p>\n<p>클래스는 속성과 메소드로 구성돼. 속성은 객체의 상태를 나타내는 데이터이고 메소드는 객체의 행동을 나타내는 함수야. </p>\n<p>클래스를 사용하면 데이터를 캡슐화할 수 있고 코드를ROUP화할 수 있어. 데이터를 캡슬화하면 데이터가 외부에서 접근되지 않도록 보호할 수 있고 코드를_GRP화하면 코드를 재사용하기 쉽도록 만들 수 있어. </p>\n<p>따라서 정답은 2번인 클래스야.</p>"]},"rate":76,"rateN":23503},{"id":"10589","number":4,"category":"소프트웨어 설계","type":"choice","subject":"데이터 흐름도(DFD)의 구성요소에 포함되지 않는 것은?","choices":[{"n":1,"html":"process"},{"n":2,"html":"data flow"},{"n":3,"html":"data store"},{"n":4,"html":"data dictionary"}],"answer":[4],"wiki":[{"title":"자료 흐름도","url":"https://itwiki.kr/w/자료 흐름도"}],"explain":{"ai":["<p>데이터 흐름도는 시스템을 분석하고 설계하는 데 사용되는 도구입니다. 데이터 흐름도는 프로세스, 데이터 흐름, 데이터 저장소의 3가지 구성요소로 구성됩니다. </p>\n<p>여기서 각 구성요소는 다음과 같은 역할을 합니다. </p>\n<ul>\n<li>프로세스란 데이터가 처리되는 활동입니다. </li>\n<li>데이터 흐름은 데이터가 이동하는 경로를 나타냅니다. </li>\n<li>데이터 저장소는 데이터가 저장되는 장소를 나타냅니다.</li>\n</ul>\n<p>반면에 데이터 사전은 데이터 흐름도에서 사용되는 데이터에 대한 정의와 설명을 제공하는 별도의 문서입니다. 데이터 사전은 데이터 흐름도를 부분적으로 구성하는 요소가 아니라 데이터 흐름도에서 사용되는 데이터의 의미를 설명해 주는 보조 도구입니다. </p>\n<p>따라서 데이터 흐름도의 구성요소에는 프로세스, 데이터 흐름, 데이터 저장소가 포함되지만 데이터 사전은 포함되지 않습니다.</p>"]},"rate":71,"rateN":24436},{"id":"10590","number":5,"category":"소프트웨어 설계","type":"choice","subject":"소프트웨어 설계시 구축된 플랫폼의 성능특성 분석에 사용되는 측정 항목이 아닌 것은?","choices":[{"n":1,"html":"응답시간(Response Time)"},{"n":2,"html":"가용성(Availability)"},{"n":3,"html":"사용률(Utilization)"},{"n":4,"html":"서버 튜닝(Server Tuning)"}],"answer":[4],"explain":{"ai":["<p>소프트웨어 설계시 구축된 플랫폼의 성능특성 분석에 사용되는 측정 항목은 응답시간, 가용성, 사용률 등이 있다. 응답시간은 사용자 요청에 대한 시스템의 응답 속도를 의미하고, 가용성은 시스템이 사용 가능한 상태를 유지하는 능력을 의미하며, 사용률은 시스템의 자원 이용률을 의미한다. </p>\n<p>서버 튜닝은 성능을 향상시키기 위한 조정 작업이다. 서버 튜닝은 성능 특성 분석의 결과에 따라 수행하는 작업이기 때문에 측정 항목은 아니다. 따라서 정답은 서버 튜닝이다.</p>"]},"rate":86,"rateN":20807},{"id":"10591","number":6,"category":"소프트웨어 설계","type":"choice","subject":"UML 확장 모델에서 스테레오 타입 객체를 표현할 때 사용하는 기호로 맞는 것은?","choices":[{"n":1,"html":"《 》"},{"n":2,"html":"(( ))"},{"n":3,"html":"{{ }}"},{"n":4,"html":"[[ ]]"}],"answer":[1],"explain":{"ai":["<p>UML 확장 모델에서 스테레오 타입 객체를 명확히 구분하고 표기할 때 사용하는 표준 기호는 《 》입니다. 이 기호는 특정 객체나 클래스가 일반적인 의미를 넘어 특수한 역할이나 스테레오 타입을 갖는다는 것을 명시적으로 나타내기 위해 설계되었습니다. 다른 옵션들인 (( )), {{ }}, [[ ]]는 UML 표준에서 스테레오 타입을 표현하는 데 사용되지 않습니다. 따라서 올바른 답은 1번 《 》입니다. 이 기호를 통해 설계자들은 코드나 다이어그램에서 특정 요소의 특수한 성격을 쉽게 식별할 수 있습니다.</p>"]},"rate":76,"rateN":22443},{"id":"10592","number":7,"category":"소프트웨어 설계","type":"choice","subject":"GoF(Gang of Four)의 디자인 패턴에서 행위 패턴에 속하는 것은?","choices":[{"n":1,"html":"Builder"},{"n":2,"html":"Visitor"},{"n":3,"html":"Prototype"},{"n":4,"html":"Bridge"}],"answer":[2],"explain":{"ai":["<p>GoF의 디자인 패턴은 크게 구조 패턴과 행위 패턴으로 나뉩니다. 행위 패턴은 주로 객체 간의 상호작용과 책임 분담을 개선하는데 초점을 맞춥니다.</p>\n<ul>\n<li><strong>Builder (빌더)</strong>: 구조 패턴으로, 복잡한 객체 생성 과정을 추상화합니다.</li>\n<li><strong>Visitor (비지터)</strong>: 행위 패턴에 속하며, 특정 연산을 여러 종류의 객체에 적용할 수 있게 해줍니다. 방문자 패턴은 객체 구조에 대한 연산을 정의하는 데 사용되며, 이를 통해 연산을 객체 구조에서 분리할 수 있습니다.</li>\n<li><strong>Prototype (프로토타입)</strong>: 생성 패턴으로, 기존 객체를 복제하여 새로운 객체를 생성하는 방식을 제공합니다.</li>\n<li><strong>Bridge (브리지)</strong>: 구조 패턴으로, 추상화와 구현을 분리하여 두 가지 모두 독립적으로 확장 가능하게 만듭니다.</li>\n</ul>\n<p>따라서 행위 패턴에 해당하는 것은 <strong>2. Visitor</strong>입니다.</p>"]},"rate":55,"rateN":29000},{"id":"10593","number":8,"category":"소프트웨어 설계","type":"choice","subject":"자료 사전에서 자료의 생략을 의미하는 기호는?","choices":[{"n":1,"html":"{ }"},{"n":2,"html":"**"},{"n":3,"html":"="},{"n":4,"html":"(　)"}],"answer":[4],"wiki":[{"title":"자료 사전","url":"https://itwiki.kr/w/자료 사전"}],"explain":{"ai":["<p>자료 사전에서 자료의 생략을 나타내는 기호는 주로 선택적 또는 가변적인 요소를 표현하는데 사용된다. 주어진 보기들 중에서:</p>\n<ol>\n<li><code>{ }</code> - 보통 반복이나 집합을 나타낼 때 사용된다.</li>\n<li><code>**</code> - 일반적으로 강조나 특정 프로그래밍 언어에서 거듭제곱을 의미할 수 있다.</li>\n<li><code>=</code> - 주로 할당 연산자나 동등성 비교에 사용된다.</li>\n</ol>\n<p>정답인 <strong>4. ( )</strong> 는 괄호 안에 내용이 생략되었거나 선택적인 입력을 나타내는 데 자주 사용된다. 특히, 자료 사전에서 어떤 값이 필요하지 않거나 상황에 따라 변할 수 있는 부분을 표시할 때 괄호를 활용하여 생략을 의미하는 경향이 있다. 따라서 자료의 생략을 가장 적절히 표현하는 기호는 ( ) 이다.</p>"]},"rate":66,"rateN":24515},{"id":"10594","number":9,"category":"소프트웨어 설계","type":"choice","subject":"트랜잭션이 올바르게 처리되고 있는지 데이터를 감시하고 제어하는 미들웨어는?","choices":[{"n":1,"html":"RPC"},{"n":2,"html":"ORB"},{"n":3,"html":"TP monitor"},{"n":4,"html":"HUB"}],"answer":[3],"wiki":[{"title":"TP 모니터","url":"https://itwiki.kr/w/TP 모니터"}],"explain":{"ai":["<p>트랜잭션이 올바르게 처리되고 있는지 데이터를 감시하고 제어하는 미들웨어는 TP 모니터입니다. TP 모니터는 트랜잭션 처리 모니터의 약자로, 데이터베이스 및 애플리케이션 서버에서 트랜잭션을 처리하며, 데이터의 일관성을 유지하고, 트랜잭션의 무결성을 보장합니다. TP 모니터는 트랜잭션 처리를 위한 표준 프로토콜을 제공하여, 다양한 데이터베이스와 애플리케이션 서버 간의 통신을 중계합니다. </p>\n<p>RPC는 원격 프로시저 호출을 위한 프로토콜입니다. ORB는 객체 요청 브로커로, 객체 지향 미들웨어를 위한 표준입니다. HUB는 네트워크 기기 중 하나로, 여러개의 컴퓨터를 연결하여 네트워크를 구성하는 기기입니다. 이러한 미들웨어는 트랜잭션 처리를 위한 데이터 감시 및 제어가 아닙니다. 따라서, 트랜잭션이 올바르게 처리되고 있는지 데이터를 감시하고 제어하는 미들웨어는 TP 모니터입니다.</p>"]},"rate":76,"rateN":21390},{"id":"10595","number":10,"category":"소프트웨어 설계","type":"choice","subject":"UI 설계 원칙에서 누구나 쉽게 이해하고 사용할 수 있어야 한다는 것은?","choices":[{"n":1,"html":"유효성"},{"n":2,"html":"직관성"},{"n":3,"html":"무결성"},{"n":4,"html":"유연성"}],"answer":[2],"wiki":[{"title":"직관성","url":"https://itwiki.kr/w/직관성"}],"explain":{"ai":["<p>UI 설계 원칙 중에서 \"누구나 쉽게 이해하고 사용할 수 있어야 한다\"는 개념은 <strong>직관성</strong>을 의미합니다. 직관성은 사용자가 인터페이스를 처음 접했을 때에도 자연스럽게 기능을 파악하고 이용할 수 있도록 설계하는 것을 강조합니다. 이는 복잡한 교육이나 설명 없이도 사용자 친화적인 환경을 제공하는 것을 목표로 합니다. 따라서 올바른 답은 2번, <strong>직관성</strong>입니다. 유효성은 입력 데이터의 정확성과 관련 있으며, 무결성은 데이터의 일관성을 유지하는 데 초점을 맞추고, 유연성은 시스템의 변경이나 확장에 대한 적응성을 의미합니다.</p>"]},"rate":90,"rateN":19110},{"id":"10596","number":11,"category":"소프트웨어 설계","type":"choice","subject":"XP(eXtreme Programming)의 5가지 가치로 거리가 먼 것은?","choices":[{"n":1,"html":"용기"},{"n":2,"html":"의사소통"},{"n":3,"html":"정형분석"},{"n":4,"html":"피드백"}],"answer":[3],"wiki":[{"title":"익스트림 프로그래밍","url":"https://itwiki.kr/w/익스트림 프로그래밍"}],"explain":{"ai":["<p>XP의 5가지 가치는 용기, 의사소통, 피드백, 단순성, 존중의 가치입니다. 이 5가지 가치는 XP의 철학과 원리를 기반으로 소프트웨어 개발에 적용되는 주요한 요소입니다. </p>\n<p>용기는 개발자들이 새로운 아이디어를 받아들이고 도전적인 목표를 설정할 수 있도록 한다는 의미입니다. 의사소통은 개발자들 간에 잘못된 이해나 오해를 줄이기 위해 투명하고 개방적인 의사소통을 중요시합니다. 피드백은 사용자와 개발자 간의 지속적인 피드백을 통해 개발과정를 개선하고 제품의 품질을 높이는 것을 강조합니다.</p>\n<p>정형분석은 XP의 가치와 거리가 먼 개념입니다. 정형분석은 소프트웨어 개발에서 엄격한과정와 공식적인 방법을 강조하는 것으로 XP의 유연하고 애자일한 접근 방식과는 다릅니다. 따라서 3번 정형분석이 XP의 5가지 가치 중에서 가장 거리가 먼 개념입니다.</p>"]},"rate":75,"rateN":22186},{"id":"10597","number":12,"category":"소프트웨어 설계","type":"choice","subject":"UML 모델에서 사용하는 Structural Diagram 에 속하지 않은 것은?","choices":[{"n":1,"html":"Class Diagram"},{"n":2,"html":"Object Diagram"},{"n":3,"html":"Component Diagram"},{"n":4,"html":"Activity Diagram"}],"answer":[4],"wiki":[{"title":"UML","url":"https://itwiki.kr/w/UML"}],"explain":{"ai":["<p>UML(Unified Modeling Language)의 Structural Diagram은 시스템의 구조적 요소와 그들 간의 관계를 나타내는 다이어그램 유형을 말합니다. 주요 종류로는 다음과 같은 것들이 포함됩니다:</p>\n<ul>\n<li><strong>Class Diagram</strong>: 클래스와 속성, 메서드, 그리고 클래스 간의 관계를 정의합니다.</li>\n<li><strong>Object Diagram</strong>: 특정 시점에서의 객체와 그들 간의 관계를 보여줍니다.</li>\n<li><strong>Component Diagram</strong>: 시스템 내 컴포넌트와 그들 간의 상호작용 및 의존성을 나타냅니다.</li>\n</ul>\n<p>반면, <strong>Activity Diagram</strong>은 Structural Diagram이 아닌 Behavior Diagram의 한 종류로, 프로세스의 흐름과 동작 순서를 표현하는 데 사용됩니다. 따라서, 주어진 보기 중 Structural Diagram에 속하지 않은 것은 4번, <strong>Activity Diagram</strong>입니다.</p>"]},"rate":74,"rateN":22728},{"id":"10598","number":13,"category":"소프트웨어 설계","type":"choice","subject":"소프트웨어 개발 방법 중 요구사항 분석(requirements annalysis)과 거리가 먼 것은?","choices":[{"n":1,"html":"비용과 일정에 대한 제약설정"},{"n":2,"html":"타당성 조사"},{"n":3,"html":"요구사항 정의 문서화"},{"n":4,"html":"설계 명세서 작성"}],"answer":[4],"wiki":[{"title":"요구사항 분석","url":"https://itwiki.kr/w/요구사항 분석"}],"explain":{"ai":["<p>요구사항 분석은 소프트웨어 개발의 초기 단계에서 요구되는 기능과 제약 조건을 식별하고 문서화하는 과정입니다. \n타당성 조사를 통해 문제의 해결 가능성과 제약 사항을 초기에 조사하고, 비용과 일정을 고려해 제약을 설정합니다. \n요구사항 정의는 분석 결과를 문서화해 의사소통을 원활하게 하며, 이 과정을 통해 후속 단계로 나아갈 수 있습니다. \n그러나 설계 명세서 작성은 요구사항을 토대로 시스템의 설계를 구체화하는 단계로, 요구사항 분석보다는 설계 단계에 관련이 있습니다. \n따라서 설계 명세서 작성은 요구사항 분석과 거리가 떨어지는 활동입니다.</p>"]},"rate":57,"rateN":27125},{"id":"10599","number":14,"category":"소프트웨어 설계","type":"choice","subject":"럼바우(Rumbaugh)의 객체지향 분석 절차를 가장 바르게 나열한 것은?","choices":[{"n":1,"html":"객체 모형→동적 모형→기능 모형"},{"n":2,"html":"객체 모형→기능 모형→동적 모형"},{"n":3,"html":"기능 모형→동적 모형→객체 모형"},{"n":4,"html":"기능 모형→객체 모형→동적 모형"}],"answer":[1],"wiki":[{"title":"럼바우 분석 기법","url":"https://itwiki.kr/w/럼바우 분석 기법"}],"explain":{"ai":["<p>럼바우의 객체지향 분석 절차는 객체지향 분석의 주요 단계를 순서대로 나열한 것이다. 이 절차는 객체지향 분석의 주요 단계인 객체 모형, 동적 모형, 기능 모형의 순서로 진행된다. </p>\n<p>먼저 객체 모형은 시스템에서 어떤 객체가(hash) 중요한 역할을 하는지, 객체 간의 관계는 어떻게 되는지를 정의한다. 동적 모형은 시간의 흐름에 따라 객체들이 어떻게 상호작용하는지를 정의하고, 기능 모형은 시스템의 기능을 정의한다. </p>\n<p>따라서 럼바우의 객체지향 분석 절차를 가장 바르게 나열한 것은 객체 모형, 동적 모형, 기능 모형의 순서로 진행되는 1번이다. 이는 객체지향 분석의 기본 원리를 따르고 있으며, 시스템을 분석하고 설계하는 데 중요한 역할을 한다.</p>"]},"rate":75,"rateN":21146},{"id":"10600","number":15,"category":"소프트웨어 설계","type":"choice","subject":"공통 모듈에 대한 명세 기법 중 해당 기능에 대해 일관되게 이해하고 한 가지로 해석될 수 있도록 작성하는 원칙은?","choices":[{"n":1,"html":"상호작용성"},{"n":2,"html":"명확성"},{"n":3,"html":"독립성"},{"n":4,"html":"내용성"}],"answer":[2],"wiki":[{"title":"공통 모듈","url":"https://itwiki.kr/w/공통 모듈"}],"explain":{"ai":["<p>정답은 2번, 명확성입니다. 공통 모듈의 명세 작성 시 가장 중요한 원칙 중 하나는 명확성입니다. 이는 모듈의 기능과 역할을 명확하게 정의하여, 모든 이해관계자가 동일한 방식으로 이해하고 해석할 수 있도록 하는 것을 의미합니다. 명확성이 확보되면 오류와 혼동이 줄어들어 개발 과정에서의 협업 효율성이 높아지고, 유지보수 또한 용이해집니다. 다른 옵션들인 상호작용성, 독립성, 내용성은 각각 다른 측면에서 중요하지만, 이 문제의 맥락에서는 기능에 대한 일관된 이해와 단일 해석이 가능하게 만드는 '명확성'이 핵심 원칙입니다.</p>"]},"rate":83,"rateN":19602},{"id":"10601","number":16,"category":"소프트웨어 설계","type":"choice","subject":"객체지향 기법에서 클래스들 사이의 ‘부분-전체(part-whole)' 관계 또는 ’부분(is-a-part-of)'의 관계로 설명되는 연관성을 나타내는 용어는?","choices":[{"n":1,"html":"일반화"},{"n":2,"html":"추상화"},{"n":3,"html":"캡슐화"},{"n":4,"html":"집단화"}],"answer":[4],"wiki":[{"title":"객체지향 연관성","url":"https://itwiki.kr/w/객체지향 연관성"},{"title":"객체지향 기법","url":"https://itwiki.kr/w/객체지향 기법"}],"explain":{"ai":["<p>객체지향 기법에서 클래스들 사이의 관계를 나타내는 용어 중 부분-전체 또는 부분의 관계로 설명되는 연관성을 나타내는 용어는 집단화이다. 이것은 객체의 전체와 부분을 나타내는 클래스 사이의 연관성을 설명하는 용어이다. 집단화는 컴포지션 또는 컨테이너-컨테이니 relationship으로도 알려져 있으며, 전체 클래스가 부분 클래스를 포함하는 관계를 나타낸다. </p>\n<p>예를 들어, 자동차와 엔진의 관계는 부분-전체의 관계로 설명될 수 있다.자동차는 전체이며, 엔진은 부분이다. 이러한 관계를 나타내는 용어가 바로 집단화이다. 다른 용어인 일반화는 상속관계을 나타내며, 추상화는 복잡한 시스템을 단순화하여 표현하는 개념이다. 캡슐화는 데이터를 숨기고 필요한 정보만 외부에 노출하는 개념이다. 따라서, 부분-전체 또는 부분의 관계를 나타내는 용어는 집단화이다.</p>"]},"rate":52,"rateN":31250},{"id":"10602","number":17,"category":"소프트웨어 설계","type":"choice","subject":"CASE가 갖고 있는 주요 기능이 아닌 것은?","choices":[{"n":1,"html":"그래픽 지원"},{"n":2,"html":"소프트웨어 생명주기 전 단계의 연결"},{"n":3,"html":"언어번역"},{"n":4,"html":"다양한 소프트웨어 개발 모형 지원"}],"answer":[3],"wiki":[{"title":"CASE","url":"https://itwiki.kr/w/CASE"}],"explain":{"ai":["<p>CASE는 컴퓨터 지원 소프트웨어 공학을 의미하며 소프트웨어 개발 및 유지보수 과정을 자동화하거나 지원하는 도구를 말한다. CASE 도구는 소프트웨어 개발 전 과정에서 사용될 수 있다. </p>\n<p>주요 기능으로는 그래픽 지원, 소프트웨어 생명주기 전 단계의 연결, 다양한 소프트웨어 개발 모형 지원 등이 있다._language번역은 CASE의 주요 기능이 아니다. 언어번역은 프로그래밍 언어를 다른 언어로 번역하는 것을 의미하는데 이는 컴파일러나 인터프리터의 역할이다. 따라서 언어번역은 CASE의 주요 기능이 아니다.</p>"]},"rate":74,"rateN":21440},{"id":"10603","number":18,"category":"소프트웨어 설계","type":"choice","subject":"DBMS 분석시 고려사항으로 거리가 먼 것은?","choices":[{"n":1,"html":"가용성"},{"n":2,"html":"성능"},{"n":3,"html":"네트워크 구성도"},{"n":4,"html":"상호 호환성"}],"answer":[3],"wiki":[{"title":"DBMS","url":"https://itwiki.kr/w/DBMS"}],"explain":{"ai":["<p>DBMS 분석시 고려사항은 데이터베이스 관리 시스템의 기능과 성능을 평가하는 것을 말한다. 이 과정에서 고려해야 할 사항들은 데이터베이스의 특성과 요구사항에 따라 다르지만 일반적으로 다음과 같은 항목들이 포함된다. </p>\n<p>가용성은 데이터베이스가 요청된 대로 언제든 접근할 수 있고 사용할 수 있는 정도를 의미하며 이는 데이터베이스의 신뢰성과 안정성을 평가하는 중요한 요소이다. </p>\n<p>성능은 데이터베이스의 처리 속도와 효율성을 평가하는 항목으로 쿼리 처리 시간, 트랜잭션 처리량, 데이터 입출력 속도 등 다양한 지표를 통해 평가한다. </p>\n<p>상호 호환성은 데이터베이스가 다른 시스템이나 소프트웨어와 함께 사용할 수 있는 정도를 의미하는데 이는 데이터 교환, 통합,<em>migration</em> 같은 작업의 효율성을 결정하는 중요한 요소이다. </p>\n<p>네트워크 구성도는 네트워크의 물리적 및 논리적 구조를 의미하며 이는 보통 데이터베이스를 포함한 전체 시스템의 설계와 구축에 관련이 있다. </p>\n<p>따라서 DBMS 분석시 고려사항으로는 주로 데이터베이스의 특성과 성능, 호환성 같은 요소들이 포함되므로, 네트워크 구성도는 DBMS 분석시 고려사항으로는 직 접적으로 가깝지 않은 항목이라고 할 수 있다.</p>"]},"rate":80,"rateN":20534},{"id":"10604","number":19,"category":"소프트웨어 설계","type":"choice","subject":"HIPO(Hierarchy Input Process Output)에 대한 설명으로 거리가 먼 것은?","choices":[{"n":1,"html":"상향식 소프트웨어 개발을 위한 문서화 도구이다."},{"n":2,"html":"HIPO 차트 종류에는 가시적 도표, 총체적 도표, 세부적 도표가 있다."},{"n":3,"html":"기능과 자료의 의존 관계를 동시에 표현할 수 있다."},{"n":4,"html":"보기 쉽고 이해하기 쉽다."}],"answer":[1],"wiki":[{"title":"HIPO","url":"https://itwiki.kr/w/HIPO"}],"explain":{"ai":["<p>HIPO란_hierarchy input process output_의 약자로 상향식이 아닌 하향식 소프트웨어 개발을 위한 문서화 도구이다. 즉 상위ระบบ 기능에서 하위의 자세한 기법으로 하여금 entwickeln 한다. 시스템의 기능적 요구를IMG화하여 분석 및 설계하는 데 사용되며 HIPO 차트의 종류에는 가시적 도표나 총체적 도표나 세부적 도표가 있다. 기능과 자료의 의존 관계를 동시에 표현할 수 있으며 보기 쉽고 이해하기 쉽다는 특징이 있다. 따라서 1번이 정답이다.</p>"]},"rate":71,"rateN":22318},{"id":"10605","number":20,"category":"소프트웨어 설계","type":"choice","subject":"객체지향 분석 방법론 중 E-R 다이어그램을 사용하여 객체의 행위를 모델링하며, 객체식별, 구조 식별, 주체 정의, 속성 및 관계 정의, 서비스 정의 등의 과정으로 구성되는 것은?","choices":[{"n":1,"html":"Coad와 Yourdon 방법"},{"n":2,"html":"Booch 방법"},{"n":3,"html":"Jacobson 방법"},{"n":4,"html":"Wirfs-Brocks 방법"}],"answer":[1],"explain":{"ai":["<p>객체지향 분석 방법론 중 E-R 다이어그램을 사용하여 객체의 행위를 모델링하며, 객체식별, 구조 식별, 주체 정의, 속성 및 관계 정의, 서비스 정의 등의 과정으로 구성되는 것은 Coad와 Yourdon 방법이다. \nCoad와 Yourdon 방법은 클래스를 정의하고 속성 및 연계를 식별하여 객체 간의 관계를 모델링하는 방법론이다. \n이 방법론은 객체지향 분석 및 설계에서 중요한 역할을 하는 것으로 알려져 있다.</p>"]},"rate":68,"rateN":22454},{"id":"10606","number":21,"category":"소프트웨어 개발","type":"choice","subject":"정렬된 N개의 데이터를 처리하는데 O(Nlog2N)의 시간이 소요되는 정렬 알고리즘은?","choices":[{"n":1,"html":"선택정렬"},{"n":2,"html":"삽입정렬"},{"n":3,"html":"버블정렬"},{"n":4,"html":"합병정렬"}],"answer":[4],"wiki":[{"title":"정렬","url":"https://itwiki.kr/w/정렬"}],"explain":{"ai":["<p>정렬 알고리즘은 데이터를 특정 순서로 나열하는 데 사용되는 알고리즘입니다. 여러 가지 정렬 알고리즘이 있는데 각 알고리즘의 시간 복잡도가 다릅니다. \n주어진 문제는 O(Nlog2N)의 시간을 소요하는 정렬 알고리즘의 종류에 대한 것입니다. 이때 시간 복잡도가 O(Nlog2N)인 알고리즘은 합병정렬, 퀵정렬, 힙정렬 등이 있습니다. \n합병정렬은 여러 개의 정렬된 자료를 하나로 통합하여 정렬하는 방식입니다. 퀵정렬은 분할 정복 방식을 이용한 정렬 알고리즘입니다. 하지만 주어진 보기에서 합병정렬만이 O(Nlog2N)의 시간 복잡도를 가집니다. \n선택정렬과 삽입정렬, 버블정렬은 O(N^2)만큼의 시간 복잡도를 가집니다. \n따라서 주어진 문제의 정답은 4번 합병정렬입니다.</p>"]},"rate":59,"rateN":24273},{"id":"10607","number":22,"category":"소프트웨어 개발","type":"choice","subject":"White Box Testing 에 대한 설명으로 옳지 않은 것은?","choices":[{"n":1,"html":"Base Path Testing, Boundary Value Analysis가 대표적인 기법이다."},{"n":2,"html":"Source Code 의 모든 문장을 한번 이상 수행함으로서 진행된다."},{"n":3,"html":"모듈 안의 작동을 직접 관찰 할 수 있다."},{"n":4,"html":"산출물의 각 기능별로 적절한 프로그램의 제어구조에 따라 선택, 반복 등의 부분들을 수행함으로써 논리적 경로를 점검한다."}],"answer":[1],"wiki":[{"title":"화이트박스 테스트","url":"https://itwiki.kr/w/화이트박스 테스트"}],"explain":{"ai":["<p>White Box Testing은 내부 코드 구조를 분석하여 테스트하는 방법으로, 주로 알고리즘의 정확성과 제어 흐름의 유효성을 검증하는데 사용됩니다.</p>\n<p>1번이 옳지 않은 설명입니다. Base Path Testing은 White Box Testing의 일부 개념과 연관성이 있지만, Boundary Value Analysis는 주로 Black Box Testing에서 주로 사용되는 기법입니다. White Box Testing의 대표적인 기법들은 Statement Coverage, Branch Coverage, Path Coverage 등에 더 집중합니다.</p>\n<p>2번은 정확합니다. White Box Testing은 소스 코드의 모든 문장이 최소한 한 번은 실행되도록 설계됩니다.</p>\n<p>3번 또한 맞는 설명으로, 개발자는 직접 코드 내부를 들여다보며 각 모듈의 동작을 직접 확인할 수 있습니다.</p>\n<p>4번은 White Box Testing의 핵심적인 특징을 잘 설명합니다. 이 방법은 프로그램의 제어 구조를 통해 다양한 논리 경로를 체계적으로 테스트합니다.</p>\n<p>따라서, 옳지 않은 설명은 1번입니다.</p>"]},"rate":59,"rateN":22243},{"id":"10608","number":23,"category":"소프트웨어 개발","type":"choice","subject":"소프트웨어 품질 측정을 위해 개발자 관점에서 고려해야 할 항목으로 거리가 먼 것은?","choices":[{"n":1,"html":"정확성"},{"n":2,"html":"무결성"},{"n":3,"html":"사용성"},{"n":4,"html":"간결성"}],"answer":[4],"explain":{"ai":["<p>개발자 관점에서 소프트웨어 품질을 측정할 때 주로 코드의 기능적 적합성과 내부 구조에 초점을 맞춥니다.</p>\n<ol>\n<li><strong>정확성</strong>: 코드가 요구 사항을 정확히 구현하는지 평가합니다.</li>\n<li><strong>무결성</strong>: 데이터의 일관성과 정확성을 유지하는 능력을 의미합니다. 오류나 변조로부터 데이터를 보호하는 측면이 강조됩니다.</li>\n<li><strong>사용성</strong>: 주로 사용자 경험에 초점을 맞추며, 인터페이스의 편의성과 사용자 친화성을 평가하는 항목입니다. 개발자 관점에서는 직접적인 관심사가 덜할 수 있습니다.</li>\n<li><strong>간결성</strong>: 코드의 효율성과 유지보수성을 나타내지만, 이 문제 맥락에서는 개발자 관점에서 가장 직접적인 품질 측정 항목으로 여겨지지 않습니다. 품질 측정에서 주로 기능적 정확성과 내부 구조의 우수성에 더 중점을 두기 때문입니다.</li>\n</ol>\n<p>따라서, 개발자 관점에서 가장 거리가 먼 항목은 <strong>간결성</strong>입니다. 정답은 4번입니다.</p>"]},"rate":61,"rateN":23376},{"id":"10609","number":24,"category":"소프트웨어 개발","type":"choice","subject":"인터페이스 구현 검증도구 중 아래에서 설명하는 것은?","extra":"<pre class=\"contents\">- 서비스 호출, 컴포넌트 재사용 등 다양한 환경을 지원하는 테스트 프레임워크\r\n- 각 테스트 대상 분산 환경에 데몬을 사용하여 테스트 대상 프로그램을 통해 테스트를 수행하고, 통합하여 자동화하는 검증 도구</pre>","choices":[{"n":1,"html":"xUnit"},{"n":2,"html":"STAF"},{"n":3,"html":"FitNesse"},{"n":4,"html":"RubyNode"}],"answer":[2],"explain":{"ai":["<p>정답은 2번 STAF입니다.</p>\n<p>지문에서 언급된 특징들은 STAF(Software Testing Automation Framework)와 정확히 일치합니다. STAF는 다양한 개발 환경과 서비스 호출, 컴포넌트 재사용 테스트를 지원하는 강력한 테스트 프레임워크입니다. 특히, 각 테스트 환경에 데몬(daemon) 프로세스를 배치하여 분산된 시스템 컴포넌트들을 효율적으로 관리하고 통합 테스트를 자동화하는 기능이 특징입니다. 이와 같은 분산 환경에서의 테스트 자동화 능력은 STAF의 핵심 가치 중 하나입니다. 반면, xUnit은 주로 단위 테스트에 초점을 맞추고, FitNesse와 RubyNode는 각각 특정 개발 방법론이나 언어에 더 특화되어 있어 지문의 설명과는 완전히 부합하지 않습니다.</p>"]},"rate":59,"rateN":23221},{"id":"10610","number":25,"category":"소프트웨어 개발","type":"choice","subject":"EAI(Enterprise Application Integration)의 구축 유형으로 옳지 않은 것은?","choices":[{"n":1,"html":"Point-to-Point"},{"n":2,"html":"Hub&Spoke"},{"n":3,"html":"Message Bus"},{"n":4,"html":"Tree"}],"answer":[4],"explain":{"ai":["<p>EAI(Enterprise Application Integration)의 주요 구축 유형은 애플리케이션 간 통합을 효과적으로 수행하기 위한 모델들을 포함한다. 올바른 유형들은 다음과 같다:</p>\n<ul>\n<li><strong>Point-to-Point</strong>: 각 애플리케이션이 직접 다른 애플리케이션과 연결되는 구조로, 단순하지만 관리 복잡성이 증가할 수 있다.</li>\n<li><strong>Hub&amp;Spoke</strong>: 중앙 허브를 통해 모든 애플리케이션이 통신하는 방식으로, 중앙 관리가 용이하다.</li>\n<li><strong>Message Bus</strong>: 메시지 브로커를 중심으로 여러 애플리케이션이 비동기적으로 통신하는 모델로, 유연성과 확장성이 뛰어나다.</li>\n</ul>\n<p>반면, <strong>Tree</strong>는 EAI의 표준 구축 유형으로 분류되지 않는다. 이는 일반적으로 계층적 데이터 구조나 네트워크 구조를 설명할 때 사용되는 용어로, EAI 통합 모델로는 적합하지 않다. 따라서 옳지 않은 구축 유형은 4번 <strong>Tree</strong>이다.</p>"]},"rate":67,"rateN":20440},{"id":"10611","number":26,"category":"소프트웨어 개발","type":"choice","subject":"다음 트리를 전위 순회(preorder traversal)한 결과는?","extra":"<img src=\"data:image/png;base64,\" style=\"padding:10px 18px; max-width:100%\">","choices":[{"n":1,"html":"+*AB/*CDE"},{"n":2,"html":"AB/C*D*E+"},{"n":3,"html":"A/B*C*D+E"},{"n":4,"html":"+**/ABCDE"}],"answer":[4],"wiki":[{"title":"트리","url":"https://itwiki.kr/w/트리"}],"rate":71,"rateN":18927,"explain":{"mine":"<p><b>핵심</b> — 전위 순회(Preorder)는 <b>Root → Left → Right</b> 순서다.</p><p>그림의 트리는 왼쪽으로만 깊게 뻗은 모양이다. 위에서부터 적어보면:</p><pre>        +\n       / \\\n      *   E\n     / \\\n    *   D\n   / \\\n  /   C\n / \\\nA   B</pre><p>루트 <code>+</code> 부터 시작해 왼쪽 자식을 계속 따라 내려가고, 각 노드에서 왼쪽을 다 끝낸 뒤 오른쪽을 방문한다.</p><ol><li><code>+</code> 방문 → 왼쪽 서브트리(<code>*</code>)로</li><li><code>*</code> 방문 → 왼쪽 서브트리(<code>*</code>)로</li><li><code>*</code> 방문 → 왼쪽 서브트리(<code>/</code>)로</li><li><code>/</code> 방문 → <code>A</code>, <code>B</code></li><li>되돌아와서 <code>C</code> → <code>D</code> → 마지막으로 <code>E</code></li></ol><p>따라서 <b>+ * * / A B C D E</b> → <b>정답 4번</b>.</p><p><b>왜 다른 건 아닌가</b><br>2번 <code>AB/C*D*E+</code> 은 후위 순회(Left→Right→Root) 결과다. 3번 <code>A/B*C*D+E</code> 은 중위 순회(Left→Root→Right) 결과이자 원래 수식 <code>A/B*C*D+E</code> 그 자체다.</p><p class=\"tip\">이 트리는 수식 <code>A/B*C*D+E</code> 의 파스 트리다. 전위 = 접두(prefix) 표기, 후위 = 접미(postfix) 표기라고 생각하면 세 순회가 한 번에 정리된다.</p>"}},{"id":"10612","number":27,"category":"소프트웨어 개발","type":"choice","subject":"인터페이스 보안을 위해 네트워크 영역에 적용될 수 있는 솔루션과 거리가 먼 것은?","choices":[{"n":1,"html":"IPSec"},{"n":2,"html":"SMTP"},{"n":3,"html":"SSL"},{"n":4,"html":"S-HTTP"}],"answer":[2],"wiki":[{"title":"이메일 프로토콜","url":"https://itwiki.kr/w/이메일 프로토콜"}],"explain":{"ai":["<p>정답은 2번(SMTP)입니다. </p>\n<p>SMTP(Simple Mail Transfer Protocol)는 주로 이메일 전송을 위한 프로토콜로, 메시지의 송수신에 초점을 맞춥니다. 인터페이스 보안이나 네트워크 트래픽의 암호화와 직접적인 관련이 없습니다.</p>\n<p>반면,</p>\n<ul>\n<li><strong>IPSec (1번)</strong>은 네트워크 계층에서 데이터 무결성과 보안을 위해 암호화 및 인증 기능을 제공합니다.</li>\n<li><strong>SSL (3번)</strong>과 <strong>S-HTTP (4번)</strong>는 모두 애플리케이션 계층에서 데이터 통신의 보안을 강화하기 위해 사용되는 암호화 프로토콜입니다. SSL은 주로 HTTPS에서 쓰이며, S-HTTP도 비슷한 목적으로 메시지 수준에서 보안을 구현합니다.</li>\n</ul>\n<p>따라서 네트워크 영역의 보안 강화에 특화된 솔루션과는 SMTP가 가장 거리가 멉니다.</p>"]},"rate":70,"rateN":18930},{"id":"10613","number":28,"category":"소프트웨어 개발","type":"choice","subject":"평가 점수에 따른 성적부여는 다음 표와 같다. 이를 구현한 소프트웨어를 경계값 분석 기법으로 테스트 하고자 할 때 다음 중 테스트 케이스의 입력 값으로 옳지 않은 것은?","extra":"<pre class=\"contents\"><table>\r\n<tr><td>평가 점수</td><td>성적</td></tr>\r\n<tr><td>80~100</td><td>A</td></tr>\r\n<tr><td>60~79</td><td>B</td></tr>\r\n<tr><td>0~59</td><td>C</td></tr>\r\n</table></pre>","choices":[{"n":1,"html":"59"},{"n":2,"html":"80"},{"n":3,"html":"90"},{"n":4,"html":"101"}],"answer":[3],"explain":{"ai":["<p>경계값 분석 기법은 입력값의 경계를 테스트하는 기법입니다. 주어진 표에서 성적을 구분하는 경계값은 80, 60, 0입니다. 테스트 케이스로 가능한 입력 값은 경계값과 경계값 바로 아래, 바로 위의 값입니다.</p>\n<p>경계값과 그 바로 아래, 위의 값인 79, 80, 59, 60, 0, -1 등을 테스트 케이스로 사용할 수 있습니다. 90은 경계와는 관련이 없는 값으로 테스트 케이스로 사용하지 않습니다. 따라서 옳지 않은 테스트 케이스의 입력 값은 90입니다.</p>"]},"rate":70,"rateN":19409},{"id":"10614","number":29,"category":"소프트웨어 개발","type":"choice","subject":"반정규화(Denormalization) 유형중 중복 테이블을 추가하는 방법에 해당하지 않는 것은?","choices":[{"n":1,"html":"빌드 테이블의 추가"},{"n":2,"html":"집계 테이블의 추가"},{"n":3,"html":"진행 테이블의 추가"},{"n":4,"html":"특정 부분만을 포함하는 테이블의 추가"}],"answer":[1],"explain":{"ai":["<p>반정규화는 데이터베이스의 성능을 향상시키기 위해 normalization 규칙을 일부 깨는 것을 말한다. 중복 테이블을 추가하는 방법은 다음과 같다. </p>\n<p>만약 특정 부분만을 포함하는 테이블의 추가라면 여기에는uilder 테이블은 포함되지 않는다. 빌드 테이블의 추가는 중복 테이블의 추가하는 방법에 해당하지 않는다. 빌드 테이블은 주로 소프트웨어 빌드 자동화 도구에서 사용된다.</p>\n<p>집계 테이블의 추가는 데이터를 집계하여 저장하는 테이블을 추가하는 것으로, 데이터의 조회 성능을 향상시키기 위한 방법이다. 진행 테이블의 추가는 데이터의 진행 상태를 관리하는 테이블을 추가하는 것으로, 데이터의 일관성을 유지하기 위한 방법이다. 특정 부분만을 포함하는 테이블의 추가는 데이터의 일부만을 저장하는 테이블을 추가하는 것으로, 데이터의 조회 성능을 향상시키기 위한 방법이다. </p>\n<p>따라서 빌드 테이블의 추가는 중복 테이블을 추가하는 방법에 해당하지 않으므로 정답은 1번이다.</p>"]},"rate":47,"rateN":26575},{"id":"10615","number":30,"category":"소프트웨어 개발","type":"choice","subject":"ISO/IEC 9126의 소프트웨어 품질 특성 중 기능서(Functionlity)의 하위 특성으로 옳지 않은 것은?","choices":[{"n":1,"html":"학습성"},{"n":2,"html":"적합성"},{"n":3,"html":"정확성"},{"n":4,"html":"보안성"}],"answer":[1],"explain":{"ai":["<p>ISO/IEC 9126의 소프트웨어 품질 특성 중 기능성 하위 특성에는 적합성, 정확성, 보안성 등이 있다. 학습성은 사용성의 하위 특성으로 분류된다. 즉 사용자의 입장에서 소프트웨어를 얼마나 쉽게 사용할 수 있는지를 뜻한다. 따라서 기능성의 하위 특성으로는 학습성이 옳지 않다.</p>"]},"rate":62,"rateN":21612},{"id":"10616","number":31,"category":"소프트웨어 개발","type":"choice","subject":"다음 트리의 차수(degree)와 단말 노드(terminal node)의 수는?","extra":"<img src=\"data:image/png;base64,\" style=\"padding:10px 18px; max-width:100%\">","choices":[{"n":1,"html":"차수: 4, 단말 노드: 4"},{"n":2,"html":"차수: 2, 단말 노드: 4"},{"n":3,"html":"차수: 4, 단말 노드: 8"},{"n":4,"html":"차수: 2, 단말 노드: 8"}],"answer":[2],"wiki":[{"title":"트리","url":"https://itwiki.kr/w/트리"}],"rate":62,"rateN":22839,"explain":{"mine":"<p><b>핵심</b> — 용어 두 개를 정확히 구분해야 한다.</p><ul><li><b>차수(Degree)</b> — 한 노드가 가진 <b>자식의 수</b>. '트리의 차수'는 그중 <b>가장 큰 값</b>이다.</li><li><b>단말 노드(Terminal / Leaf)</b> — 자식이 <b>없는</b> 노드, 즉 차수가 0인 노드.</li></ul><p>그림의 트리를 정리하면:</p><pre>      A\n     / \\\n    B   C\n   /   / \\\n  D   E   F\n     / \\\n    G   H</pre><p><b>차수 계산</b> — A는 자식 2개(B, C), B는 1개(D), C는 2개(E, F), E는 2개(G, H). 최댓값은 <b>2</b>이므로 트리의 차수는 2다.</p><p><b>단말 노드</b> — 자식이 없는 노드는 <b>D, G, H, F</b> 로 <b>4개</b>다.</p><p>따라서 <b>차수 2, 단말 노드 4 → 정답 2번</b>.</p><p><b>함정</b><br>전체 노드 수(8개)를 단말 노드 수로 착각하게 만든 보기가 3·4번이다. 또 '차수 4'는 트리에 노드가 4레벨이라는 점을 노린 오답이다. <b>차수는 레벨·깊이와 무관</b>하다.</p>"}},{"id":"10617","number":32,"category":"소프트웨어 개발","type":"choice","subject":"디지털 저작권 관리(DRM)의 기술 요소가 아닌 것은?","choices":[{"n":1,"html":"크랙 방지 기술"},{"n":2,"html":"정책 관리 기술"},{"n":3,"html":"암호화 기술"},{"n":4,"html":"방화벽 기술"}],"answer":[4],"wiki":[{"title":"DRM","url":"https://itwiki.kr/w/DRM"}],"explain":{"ai":["<p>디지털 저작권 관리 기술은 디지털 콘텐츠의 무단 복제나 배포를 막는 기술입니다. \n크랙 방지 기술, 정책 관리 기술, 암호화 기술은 모두 디지털 콘텐츠의 보안과 관리를 위해 사용되는 기술들이므로 디지털 저작권 관리 기술의 요소입니다.\nHowever, 방화벽 기술은 네트워크 보안을 위한 기술로 디지털 콘텐츠의 관리와는 직접적으로 관련이 없기 때문에 디지털 저작권 관리 기술의 요소는 아닙니다. \n따라서 정답은 4번입니다. \n이 기술은 네트워크의 보안을 강화하는 데 사용되기 때문에 디지털 저작권 관리 기술과는 별개의 영역입니다.</p>"]},"rate":71,"rateN":19063},{"id":"10618","number":33,"category":"소프트웨어 개발","type":"choice","subject":"소프트 웨어 테스트에서 오류의 80%는 전체 모듈의 20% 내에서 발견된다는 법칙은?","choices":[{"n":1,"html":"Brooks의 법칙"},{"n":2,"html":"Boehm의 법칙"},{"n":3,"html":"Pareto의 법칙"},{"n":4,"html":"Jackson의 법칙"}],"answer":[3],"wiki":[{"title":"파레토 원칙","url":"https://itwiki.kr/w/파레토 원칙"},{"title":"브룩스의 법칙","url":"https://itwiki.kr/w/브룩스의 법칙"}],"explain":{"ai":["<p>소프트웨어 테스트에서 오류의 80%는 전체 모듈의 20% 내에서 발견된다는 법칙은 Pareto의 법칙이라고 알려져 있습니다. 이 법칙은 일반적으로 많은 결과의 원인이 비교적 적은 원인에 의해 발생한다는 것을 의미하며, 소프트웨어 테스트에서도 같은 원리가 적용됩니다. 즉, 소프트웨어의 오류 대부분은 전체 코드의 일부 작은 부분에서 발생한다는 것을 의미합니다. 이 법칙은 결함이 집중되는 비율을 설명하며, 개발자와 테스터에게 중요한 가이드를 제공합니다.</p>"]},"rate":67,"rateN":20247},{"id":"10619","number":34,"category":"소프트웨어 개발","type":"choice","subject":"소프트웨어 형상 관리의 의미로 적절한 것은?","choices":[{"n":1,"html":"비용에 관한 사항을 효율적으로 관리하는 것"},{"n":2,"html":"개발 과정의 변경 사항을 관리하는 것"},{"n":3,"html":"테스트 과정에서 소프트웨어를 통합하는 것"},{"n":4,"html":"개발 인력을 관리하는 것"}],"answer":[2],"wiki":[{"title":"형상 관리","url":"https://itwiki.kr/w/형상 관리"}],"explain":{"ai":["<p>소프트웨어 형상 관리는 개발 과정에서 변경 사항이 발생할 때마다 이를 관리하고 추적하는 것을 의미한다. 이는 소프트웨어의 안정성과 일관성을 유지하기 위한 중요한 과정이다. 변경 사항이 발생하면 이를 확인하고 승인한 후에만 변경이 적용되어야 하며, 변경 내역은 모두 기록되어야 한다. </p>\n<p>소프트웨어 형상 관리의 목적은 소프트웨어의 품질을 높이고, 개발 과정의 효율성을 개선하며, 유지 보수가 용이하도록 하는 것이다. 이를 통해 소프트웨어의 안정성과 일관성을 보장할 수 있다. </p>\n<p>따라서 개발 과정의 변경 사항을 관리하는 것을 의미하는 2번이 정답이다. 다른 선택지들은 소프트웨어 형상 관리의 정의에 일치하지 않는다.</p>"]},"rate":69,"rateN":19650},{"id":"10620","number":35,"category":"소프트웨어 개발","type":"choice","subject":"알고리즘 시간복잡도 O(I)이 의미하는 것은?","choices":[{"n":1,"html":"컴퓨터 처리가 불가"},{"n":2,"html":"알고리즘 입력 데이터 수가 한 개"},{"n":3,"html":"알고리즘 수행시간이 입력 데이터 수와 관계없이 일정"},{"n":4,"html":"알고리즘 길이가 입력 데이터보다 작음"}],"answer":[3],"wiki":[{"title":"점근적 표기법","url":"https://itwiki.kr/w/점근적 표기법"}],"explain":{"ai":["<p>알고리즘 시간복잡도 O(1)이 의미하는 것은 입력 데이터의 크기에 관계없이 알고리즘의 수행 시간이 일정하다는 것을 뜻한다. 즉, 알고리즘의 실행 속도는 입력 크기에 영향을 받지 않는다는 것을 의미한다. 이는 알고리즘이 일정한 시간 안에 수행될 수 있음을 보장한다. 이러한 시간복잡도를 콘스탄트 시간복잡도라고도 부른다. 이는 데이터의 크기가 늘어나더라도 알고리즘의 수행 시간이 동일하게 유지된다는 것을 의미한다.</p>"]},"rate":79,"rateN":17579},{"id":"10621","number":36,"category":"소프트웨어 개발","type":"choice","subject":"소스코드 품질분석 도구 중 정적분석 도구가 아닌 것은?","choices":[{"n":1,"html":"pmd"},{"n":2,"html":"cppcheck"},{"n":3,"html":"valMeter"},{"n":4,"html":"checkstyle"}],"answer":[3],"explain":{"ai":["<p>소스코드 품질분석 도구에는 정적분석과 동적분석이 있습니다. 정적분석은 실제 코드가 실행되지 않은 채로 코드 자체를 분석하여 코드의 품질을 평가하는 것을 말합니다. \npmd와 cppcheck, checkstyle은 모두 소스코드의 코드스멜, 코드 포맷팅, 코드의 복잡도, 나쁨 코드 등 코드 자체의 품질을 평가하여 개선해야 할 부분을 알려줍니다. \nvalMeter는 실제 코드가 실행되는 동적인 코드의 성능에 대한 분석을 함으로써 소스코드의 동적 분석 도구로 볼 수 있습니다. \n따라서 위의 4가지 도구 중에 정적분석 도구가 아닌 것은 valMeter입니다.</p>"]},"rate":61,"rateN":20944},{"id":"10622","number":37,"category":"소프트웨어 개발","type":"choice","subject":"검증 검사 기법 중 개발자의 장소에서 사용자가 개발자 앞에서 행하는 기법이며, 일반적으로 통제된 환경에서 사용자와 개발자가 함께 확인하면서 수행되는 검사는?","choices":[{"n":1,"html":"동치 분할 검사"},{"n":2,"html":"형상 검사"},{"n":3,"html":"알파 검사"},{"n":4,"html":"베타 검사"}],"answer":[3],"wiki":[{"title":"인수 테스트","url":"https://itwiki.kr/w/인수 테스트"}],"explain":{"ai":["<p>알파 검사는 소프트웨어 개발 과정에서 개발자의 현장에서 직접 사용자가 참여하여 시스템을 테스트하는 방법입니다. 이 검사는 주로 통제된 환경에서 이루어지며, 개발자와 사용자가 함께 참여하여 시스템의 기능과 사용성을 실시간으로 검증합니다. 이 과정을 통해 초기 단계에서 버그를 발견하고 수정할 수 있어, 소프트웨어의 품질 향상에 중요한 역할을 합니다. 따라서 주어진 조건에 가장 부합하는 정답은 <strong>알파 검사 (3번)</strong> 입니다. 베타 검사와 달리, 알파 검사는 개발자 측에서 관리되는 제한된 범위 내에서 진행됩니다.</p>"]},"rate":72,"rateN":18564},{"id":"10623","number":38,"category":"소프트웨어 개발","type":"choice","subject":"하향식 통합에 있어서 모듈 간의 통합 시험을 위해 일시적으로 필요한 조건만을 가지고 임시로 제공되는 시험용 모듈을 무엇이라고 하는가?","choices":[{"n":1,"html":"Stub"},{"n":2,"html":"Driver"},{"n":3,"html":"Procedure"},{"n":4,"html":"Function"}],"answer":[1],"wiki":[{"title":"통합 테스트","url":"https://itwiki.kr/w/통합 테스트"}],"explain":{"ai":["<p>하향식 통합은 프로그램을 구성하는 모듈을 하위로 분해하여 하나씩 시험하고 통합하는 방식이다. 이러한 과정에서 모듈 간의 통합 시험을 위해 일시적으로 필요한 조건만을 가지고 임시로 제공되는 시험용 모듈이 필요하다. 이때 사용되는 모듈을 Stub이라고 한다. Stub은 하위 모듈이 아직 개발되지 않았거나, 시험을 위한 입력 또는 출력을 제공해야 할 때 사용된다. 따라서_stub을 이용하여 모듈 간의 통합 시험을 진행할 수 있다.</p>"]},"rate":79,"rateN":17323},{"id":"10624","number":39,"category":"소프트웨어 개발","type":"choice","subject":"SW 패키징 도구 활용 시 고려 사항과 거리가 먼 것은?","choices":[{"n":1,"html":"패키징 시 사용자에게 배포되는 SW이므로 보안을 고려한다."},{"n":2,"html":"사용자 편의성을 위한 복합성 및 비효율성 문제를 고려한다."},{"n":3,"html":"보안상 단일 기종에서만 사용할 수 있도록 해야 한다."},{"n":4,"html":"제품 SW 종류에 적합한 암호화 알고리즘을 적용한다."}],"answer":[3],"explain":{"ai":["<p>SW 패키징 도구는 소프트웨어 배포를 쉽게 하기 위해 사용된다. 이 때 고려해야 할 사항은 사용자에게 안전하고 효율적인 소프트웨어를 제공하는 것이다. 보안을 고려하여 사용자 데이터와 시스템을 보호해야 하며, 사용자 편의성을 위해 복합성과 비효율성 문제를 해결해야 한다. 또한 제품 소프트웨어의 종류에 적합한 암호화 알고리즘을 적용하여 데이터를 보호해야 한다.</p>\n<p>하지만 보안상 단일 기종에서만 사용할 수 있도록 해야 한다는 것은 지나치게 제한적인 조건이다. 이는 사용자의 편의성과 효율성을 저해할 수 있으며, 실제로 많은 소프트웨어는 여러 기종에서 사용될 수 있도록 설계된다. 따라서 이 조건은 SW 패키징 도구 활용 시 고려 사항과 거리가 먼 것으로 볼 수 있다.</p>"]},"rate":91,"rateN":15069},{"id":"10625","number":40,"category":"소프트웨어 개발","type":"choice","subject":"외계인코드(Alien Code)에 대한 설명으로 옳은 것은?","choices":[{"n":1,"html":"프로그램의 로직이 복잡하여 이해하기 어려운 프로그램을 의미한다."},{"n":2,"html":"아주 오래되거나 참고문서 또는 개발자가 없어 유지보수 작업이 어려운 프로그램을 의미한다."},{"n":3,"html":"오류가 없어 디버깅 과정이 필요 없는 프로그램을 의미한다."},{"n":4,"html":"사용자가 직접 작성한 프로그램을 의미한다."}],"answer":[2],"wiki":[{"title":"외계인 코드","url":"https://itwiki.kr/w/외계인 코드"}],"explain":{"ai":["<p>외계인코드는 아주 오래되거나 참고문서 또는 개발자가 없어 유지보수 작업이 어려운 프로그램을 의미한다. 이는 개발자가 변경되거나 소스 코드가 파손되어 유지보수가 어려운 상태를 뜻한다. 일반적으로는 개발자들이 코드를 작성할 때 이해하기 쉽게 작성해야 하지만 외계인코드의 경우 코드의 로직이나 구조가 이해하기 어려워서 유지보수 작업이 힘들다.</p>"]},"rate":81,"rateN":16604},{"id":"10626","number":41,"category":"데이터베이스 구축","type":"choice","subject":"SQL 의 분류 중 DDL에 해당하지 않는 것은?","choices":[{"n":1,"html":"UPDATE"},{"n":2,"html":"ALTER"},{"n":3,"html":"DROP"},{"n":4,"html":"CREATE"}],"answer":[1],"wiki":[{"title":"DDL","url":"https://itwiki.kr/w/DDL"}],"explain":{"ai":["<p>DDL(데이터 정의어)은 데이터베이스의 구조를 정의하고 변경하는 데 사용되는 SQL 명령어 집합입니다. 주요 DDL 명령어로는 테이블이나 인덱스 등의 객체를 생성(<code>CREATE</code>), 수정(<code>ALTER</code>), 삭제(<code>DROP</code>)하는 기능이 포함됩니다.</p>\n<ul>\n<li><code>CREATE</code>: 데이터베이스 객체 생성</li>\n<li><code>ALTER</code>: 기존 객체의 구조 수정</li>\n<li><code>DROP</code>: 데이터베이스 객체 삭제</li>\n</ul>\n<p>반면, <code>UPDATE</code>는 데이터의 내용을 직접 수정하는 DML(데이터 조작어)에 속합니다. 따라서 DDL에 해당하지 않습니다. 따라서 정답은 1번 <code>UPDATE</code>입니다.</p>"]},"rate":66,"rateN":20164},{"id":"10627","number":42,"category":"데이터베이스 구축","type":"choice","subject":"다음 두 릴레이션에서 외래키로 사용된 것은? (단 밑줄 친 속성은 기본키이다.)","extra":"<pre class=\"contents\">과목(<u>과목번호</u>, 과목명)\r\n수강(<u>수강번호</u>, 학번, 과목번호, 학기)</pre>","choices":[{"n":1,"html":"수강번호"},{"n":2,"html":"과목번호"},{"n":3,"html":"학번"},{"n":4,"html":"과목명"}],"answer":[2],"wiki":[{"title":"데이터베이스 키","url":"https://itwiki.kr/w/데이터베이스 키"}],"explain":{"ai":["<p>외래키는 다른 릴레이션의 기본키를 참조하는 속성으로, 데이터의 일관성과 참조 무결성을 유지하는 데 사용됩니다. 문제의 지문에서 과목번호는 과목 릴레이션의 기본키로 표시되어 있습니다. 수강 릴레이션에서 과목번호는 외부의 과목번호를 참조하고 있어, 이는 과목번호가 수강 릴레이션 내의 외래키 역할을 함을 나타냅니다. 따라서 정답은 과목번호를 외래키로 사용하는 2번입니다. 학번은 수강 정보와 관련이 있지만, 주어진 정보에서 다른 릴레이션의 기본키를 직접 참조하는 역할은 하지 않습니다. 수강번호는 수강 릴레이션의 기본키이므로 외래키가 아닙니다. 과목명은 기본키가 아니며 참조 관계의 핵심 요소가 아니므로 정답이 될 수 없습니다.</p>"]},"rate":86,"rateN":16276},{"id":"10628","number":43,"category":"데이터베이스 구축","type":"choice","subject":"데이터 무결성 제약조건 중 “개체 무결성 제약”조건에 대한 설명으로 맞는 것은?","choices":[{"n":1,"html":"릴레이션 내의 튜플들이 각 속성의 도메인에 지정된 값만을 가져야 한다."},{"n":2,"html":"기본키에 속해 있는 애트리뷰트는 널값이나 중복값을 가질 수 없다."},{"n":3,"html":"릴레이션은 참조할 수 없는 외래키 값을 가질 수 없다."},{"n":4,"html":"외래키 값은 참조 릴레이션의 기본키 값과 동일해야 한다."}],"answer":[2],"explain":{"ai":["<p>데이터 무결성 제약조건 중 개체 무결성 제약은 릴레이션에서 기본키의 속성에 대해 정의된다. 개체 무결성 제약의 주요 내용은 기본키에 속하는 속성 값은 중복되지 말아야 하고 널값을 가져서는 안된다는 것이다. 이러한 제약은 각 튜플이 릴레이션 내에서 고유한 식별자를 가질 수 있도록 하여 데이터의 일관성과 정확성을 보장한다. 따라서 2번이 정답이다. 다른 보기들은 데이터 무결성의 다른 측면을 설명한다. 1번은 도메인 무결성, 3번과 4번은 참조 무결성에 대한 설명이다. 그러므로 2번이 가장 적절한 설명이다.</p>"]},"rate":69,"rateN":18500},{"id":"10629","number":44,"category":"데이터베이스 구축","type":"choice","subject":"뷰(view)에 대한 설명으로 옳지 않은 것은?","choices":[{"n":1,"html":"뷰는 CREATE 문을 사용하여 정의한다."},{"n":2,"html":"뷰는 데이터의 논리적 독립성을 제공한다."},{"n":3,"html":"뷰를 제거할 때에는 DROP 문을 사용한다."},{"n":4,"html":"뷰는 저장장치 내에 물리적으로 존재한다."}],"answer":[4],"wiki":[{"title":"데이터베이스 뷰","url":"https://itwiki.kr/w/데이터베이스 뷰"}],"explain":{"ai":["<p>정답은 4번입니다. 뷰는 논리적 구조로, 물리적인 테이블과 달리 실제 데이터를 독립적으로 저장하지 않습니다. 뷰는 기본 테이블의 가상 표현이며, 쿼리 실행 시에만 해당 내용이 처리됩니다. 따라서 뷰는 저장장치 내에 물리적으로 직접 데이터를 저장하지 않고, 필요할 때 기반 테이블의 데이터를 가공하여 보여주는 역할만 합니다. 이는 다른 옵션들(뷰 생성, 논리적 독립성 제공, 삭제 방법 등)이 모두 정확한 설명임을 강조합니다.</p>"]},"rate":81,"rateN":16348},{"id":"10630","number":45,"category":"데이터베이스 구축","type":"choice","subject":"다음 SQL 문의 실행 결과는?","extra":"<pre class=\"contents\">SELECT 가격 FROM 도서가격\r\nWHERE 책번호=(SELECT 책번호 FROM 도서 WHERE 책명='자료구조');\r\n\r\n<table>\r\n  <tr>\r\n    <th colspan=\"2\">도서</th>\r\n  </tr>\r\n\r\n\r\n  <tr>\r\n    <td>책번호</td>\r\n    <td>책명</td>\r\n  </tr>\r\n  <tr>\r\n    <td>111</td>\r\n    <td>운영체제</td>\r\n  </tr>\r\n  <tr>\r\n    <td>222</td>\r\n    <td>자료구조</td>\r\n  </tr>\r\n  <tr>\r\n    <td>333</td>\r\n    <td>컴퓨터구조</td>\r\n  </tr>\r\n\r\n</table>\r\n\r\n<table>\r\n\r\n  <tr>\r\n    <th colspan=\"2\">도서 가격</th>\r\n  </tr>\r\n\r\n\r\n  <tr>\r\n    <td>책번호</td>\r\n    <td>가격</td>\r\n  </tr>\r\n  <tr>\r\n    <td>111</td>\r\n    <td>20,000</td>\r\n  </tr>\r\n  <tr>\r\n    <td>222</td>\r\n    <td>25,000</td>\r\n  </tr>\r\n  <tr>\r\n    <td>333</td>\r\n    <td>10,000</td>\r\n  </tr>\r\n  <tr>\r\n    <td>444</td>\r\n    <td>15,000</td>\r\n  </tr>\r\n\r\n</table></pre>","choices":[{"n":1,"html":"10,000"},{"n":2,"html":"15,000"},{"n":3,"html":"20,000"},{"n":4,"html":"25,000"}],"answer":[4],"explain":{"ai":["<p>도서 테이블에서 책명이 '자료구조'인 책의 책번호는 222이다. 이 값을 도서 가격 테이블에서 찾으면 가격은 25,000이다. 따라서 실행 결과는 25,000이다.</p>"]},"rate":95,"rateN":13834},{"id":"10631","number":46,"category":"데이터베이스 구축","type":"choice","subject":"데이터베이스의 논리적 설계(logical design) 단계에서 수행하는 작업이 아닌 것은?","choices":[{"n":1,"html":"레코드 집중의 분석 및 설계"},{"n":2,"html":"논리적 데이터베이스 구조로 매핑(mapping)"},{"n":3,"html":"트랜잭션 인터페이스 설계"},{"n":4,"html":"스키마의 평가 및 정제"}],"answer":[1],"wiki":[{"title":"데이터 모델링","url":"https://itwiki.kr/w/데이터 모델링"}],"explain":{"ai":["<p>데이터베이스의 논리적 설계 단계는 데이터베이스의 구조와 관계를 정의하는 단계입니다. 이 단계에서는 데이터베이스의 논리적 구조를 설계하고, 엔티티 간의 관계를 정의합니다.</p>\n<p>각 보기에서 수행하는 작업을 살펴보면,</p>\n<ul>\n<li>2번: 논리적 데이터베이스 구조로 매핑은 논리적 설계 단계에서 수행하는 작업입니다. 이는 개념적 모델을 논리적 모델로 변환하는 과정입니다.</li>\n<li>3번: 트랜잭션 인터페이스 설계는 논리적 설계 단계에서 수행하는 작업입니다. 이는 사용자와 데이터베이스 간의 인터페이스를 설계하는 과정입니다.</li>\n<li>4번: 스키마의 평가 및 정제는 논리적 설계 단계에서 수행하는 작업입니다. 이는 설계된 스키마를 평가하고, 필요한 경우 수정하는 과정입니다.</li>\n</ul>\n<p>반면에, </p>\n<ul>\n<li>1번: 레코드 집중의 분석 및 설계는 물리적 설계 단계에서 수행하는 작업입니다. 이는 데이터를 저장하고 관리하는 방법을 결정하는 과정입니다.</li>\n</ul>\n<p>따라서, 데이터베이스의 논리적 설계 단계에서 수행하는 작업이 아닌 것은 1번입니다.</p>"]},"rate":44,"rateN":29686},{"id":"10632","number":47,"category":"데이터베이스 구축","type":"choice","subject":"이행적 함수 종속 관계를 의미하는 것은?","choices":[{"n":1,"html":"A→B이고 B→C 일 때, A→C를 만족하는 관계"},{"n":2,"html":"A→B이고 B→C 일 때, C→A를 만족하는 관계"},{"n":3,"html":"A→B이고 B→C 일 때, B→A를 만족하는 관계"},{"n":4,"html":"A→B이고 B→C 일 때, C→B를 만족하는 관계"}],"answer":[1],"wiki":[{"title":"함수적 종속성","url":"https://itwiki.kr/w/함수적 종속성"}],"explain":{"ai":["<p>이행적 함수 종속 관계는 특정 속성들 사이에서 함수 종속 관계가 전이되는 경우를 말한다. \n예를 들어 속성 A가 속성 B를 결정하고, 속성 B가 속성 C를 결정한다면, 속성 A는 속성 C를 결정한다는 것을 의미한다. \n따라서 A→B이고 B→C 일 때, A→C를 만족하는 관계가 이행적 함수 종속 관계를 의미한다. \n이런 경우에 속성 A는 속성 C에 대해 함수 종속관계가 있다. \n이와 같은 유형의 함수 종속관계를 표현한 것이 1번이다.</p>"]},"rate":87,"rateN":15159},{"id":"10633","number":48,"category":"데이터베이스 구축","type":"choice","subject":"하나의 애트리뷰트가 가질 수 있는 원자값들의 집합을 의미하는 것은?","choices":[{"n":1,"html":"도메인"},{"n":2,"html":"튜플"},{"n":3,"html":"엔티티"},{"n":4,"html":"다형성"}],"answer":[1],"explain":{"ai":["<p>정답은 1번입니다. 도메인이란 데이터베이스에서 특정 애트리뷰트(속성)가 가질 수 있는 모든 가능한 원자값들의 집합을 의미합니다. 이는 데이터의 종류와 제약 조건을 정의하는 데 사용되며, 각 필드에 허용되는 값의 범위와 유형을 명확히 합니다.</p>\n<ul>\n<li>튜플은 관계형 데이터베이스의 행을 나타내며, 여러 애트리뷰트의 값들의 집합입니다.</li>\n<li>엔티티는 데이터베이스 설계에서 독립적으로 존재하는 실제 객체나 개념을 의미합니다.</li>\n<li>다형성은 주로 객체 지향 프로그래밍에서 동일한 인터페이스나 메서드가 다양한 타입의 객체에 대해 다르게 동작하는 특성을 말하며, 데이터베이스 용어와는 직접 관련이 없습니다.</li>\n</ul>\n<p>따라서 애트리뷰트의 가능한 값의 범위를 정의하는 개념은 도메인입니다.</p>"]},"rate":61,"rateN":21963},{"id":"10634","number":49,"category":"데이터베이스 구축","type":"choice","subject":"STUDENT 테이블에 독일어과 학생 50명, 중국어과 학생 30명, 영어영문학과 학생 50명의 정보가 저장되어 있을 때, 다음 두 SQL문의 실행 결과 튜플 수는? (단, DEPT 컬럼은 학과명)","extra":"<pre class=\"contents\">ⓐ SELECT DEPT FROM STUDENT;\r\nⓑ SELECT DISTINCT DEPT FROM STUDENT;</pre>","choices":[{"n":1,"html":"ⓐ 3, ⓑ 3"},{"n":2,"html":"ⓐ 50, ⓑ 3"},{"n":3,"html":"ⓐ 130, ⓑ 3"},{"n":4,"html":"ⓐ 130, ⓑ 130"}],"answer":[3],"explain":{"ai":["<p>STUDENT 테이블에 각 과의 학생 정보가 저장되어 있을 때 실행 결과를 확인해보면 \n첫번째 SQL문인 ⓐ SELECT DEPT FROM STUDENT; 는 STUDENT 테이블의 DEPT 컬럼의 모든 값을 불러오기 때문에 전체 학생 수인 130개의 튜플이 나옵니다. \n두번째 SQL문인 ⓑ SELECT DISTINCT DEPT FROM STUDENT; 는 STUDENT 테이블의 DEPT 컬럼에서 중복된 값을 제거하고 나열하므로 각 과별로 하나씩 총 3개의 튜플이 나옵니다. \n따라서 실행 결과 튜플 수는 ⓐ 130, ⓑ 3입니다.</p>"]},"rate":82,"rateN":15801},{"id":"10635","number":50,"category":"데이터베이스 구축","type":"choice","subject":"관계대수 연산에서 두 릴레이션이 공통으로 가지고 있는 속성을 이용하여 두 개의 릴레이션을 하나로 합쳐서 새로운 릴레이션을 만드는 연산은?","choices":[{"n":1,"html":"⋈"},{"n":2,"html":"⊃"},{"n":3,"html":"π"},{"n":4,"html":"σ"}],"answer":[1],"wiki":[{"title":"관계대수","url":"https://itwiki.kr/w/관계대수"}],"explain":{"ai":["<p>관계대수 연산에서 두 릴레이션을 하나로 합쳐 새로운 릴레이션을 만드는 연산은 조인 연산이다. 조인 연산은 두 릴레이션이 공통으로 가지고 있는 속성을 이용해 릴레이션을 결합한다. </p>\n<p>관계대수 연산에서 조인 연산은 ⋈ 기호로 표기한다. 따라서 두 릴레이션을 하나로 합쳐 새로운 릴레이션을 만드는 연산은 ⋈ 기호를 사용하는 조인 연산이다. </p>\n<p>조인 연산을 통해 관련된 데이터를 하나의 릴레이션으로 통합할 수 있어 데이터베이스에서 데이터를 효율적으로 관리하고 조회할 수 있다. </p>\n<p>따라서 릴레이션을 결합하는 연산은 1번 ⋈이다.</p>"]},"rate":76,"rateN":17726},{"id":"10636","number":51,"category":"데이터베이스 구축","type":"choice","subject":"트랜잭션의 특성 중 다음 설명에 해당하는 것은?","extra":"<pre class=\"contents\">트랜잭션의 연산은 데이터베이스에 모두 반영되든지 아니면 전혀 반영되지 않아야 한다.</pre>","choices":[{"n":1,"html":"Durability"},{"n":2,"html":"Share"},{"n":3,"html":"Consistency"},{"n":4,"html":"Atomicity"}],"answer":[4],"wiki":[{"title":"트랜잭션 특성","url":"https://itwiki.kr/w/트랜잭션 특성"}],"explain":{"ai":["<p>트랜잭션의 특성을 설명하는 문장이다. 트랜잭션은 데이터베이스의 일관성을 유지하기 위해 필요한 성질 중 하나가 원자성이다. 원자성은 트랜잭션의 연산이 모두 성공적으로 완료되거나 아무런 영향을 미치지 않아야 한다는 것을 의미한다. 데이터베이스에 반영되는 과정에서 문제가 발생하여 트랜잭션의 연산을 부분적으로만 적용할 수 없다는 것이다. 이렇게 되면 데이터베이스의 일관성이 깨질 수 있기 때문이다. 따라서 트랜잭션의 연산은 모두 성공하면 데이터베이스에 반영시키고, 하나라도 실패하면 전혀 반영되지 않아야 한다. 이런 특성이 바로 원자성이다.</p>"]},"rate":68,"rateN":18356},{"id":"10637","number":52,"category":"데이터베이스 구축","type":"choice","subject":"분산 데이터베이스 목표 중 “데이터베이스의 분산된 물리적 환경에서 특정 지역의 컴퓨터 시스템이나 네트워크에 장애가 발생해도 데이터 무결성이 보장된다”는 것과 관계있는 것은?","choices":[{"n":1,"html":"장애 투명성"},{"n":2,"html":"병행 투명성"},{"n":3,"html":"위치 투명성"},{"n":4,"html":"중복 투명성"}],"answer":[1],"wiki":[{"title":"분산 데이터베이스","url":"https://itwiki.kr/w/분산 데이터베이스"}],"explain":{"ai":["<p>분산 데이터베이스는 데이터가 여러 곳에 분산되어 저장되는 데이터베이스를 말한다. 이 경우 각 지역의 컴퓨터 시스템이나 네트워크에 장애가 발생하면 데이터에 접근할 수 없게 되므로 데이터 무결성이 깨질 수 있다. </p>\n<p>이러한 문제를 해결하기 위해 분산 데이터베이스는 장애 투명성을 제공한다. 장애 투명성이란 사용자가 데이터베이스를 사용할 때 특정 지역의 컴퓨터 시스템이나 네트워크에 장애가 발생해도 데이터에 접근할 수 있게 해주는 것을 말한다. </p>\n<p>즉, 장애 투명성은 데이터베이스의 분산된 물리적 환경에서 특정 지역의 컴퓨터 시스템이나 네트워크에 장애가 발생해도 데이터 무결성이 보장되는 것을 의미한다. </p>\n<p>따라서 분산 데이터베이스 목표 중 “데이터베이스의 분산된 물리적 환경에서 특정 지역의 컴퓨터 시스템이나 네트워크에 장애가 발생해도 데이터 무결성이 보장된다”는 것과 관련된 것은 장애 투명성이다.</p>"]},"rate":67,"rateN":19523},{"id":"10638","number":53,"category":"데이터베이스 구축","type":"choice","subject":"데이터베이스 시스템에서 삽입, 갱신, 삭제 등의 이벤트가 발생할 때마다 관련 작업이 자동으로 수행되는 절차형 SQL은?","choices":[{"n":1,"html":"트리거(rtigger)"},{"n":2,"html":"무결성(integrity)"},{"n":3,"html":"잠금(lock)"},{"n":4,"html":"복귀(rollback)"}],"answer":[1],"explain":{"ai":["<p>데이터베이스 시스템에서 삽입, 갱신, 삭제 등의 이벤트가 발생할 때마다 관련 작업이 자동으로 수행되는 절차형 SQL을 트리거라고 한다. 트리거는 특정한 이벤트가 발생했을 때 자동으로 실행되는 절차형 SQL문을 의미한다. 예를 들어, 데이터가 삽입되거나 갱신될 때마다 관련된 로그 데이터를 자동으로 삽입하거나 갱신하는 경우에 트리거를 사용할 수 있다. 따라서 데이터베이스 시스템에서 자동으로 수행되는 작업을 정의하는 트리거가 정답이다. 트리거는 데이터 일관성을 유지하고 데이터베이스의 무결성을 보장하는 데 중요한 역할을 한다. 또한 데이터베이스 관리자가 수동으로 작업을 수행하지 않더라도 자동으로 관련 작업을 수행할 수 있도록 해준다.</p>"]},"rate":81,"rateN":16259},{"id":"10639","number":54,"category":"데이터베이스 구축","type":"choice","subject":"참조 무결성을 유지하기 위하여 DROP문에서 부모 테이블의 항목 값을 삭제할 경우 자동적으로 자식 테이블의 해당 레코드를 삭제하기 위한 옵션은?","choices":[{"n":1,"html":"CLUSTER"},{"n":2,"html":"CASCADE"},{"n":3,"html":"SET-NULL"},{"n":4,"html":"RESTRICTED"}],"answer":[2],"wiki":[{"title":"참조 무결성 제약","url":"https://itwiki.kr/w/참조 무결성 제약"}],"explain":{"ai":["<p>참조 무결성을 유지하기 위한 방법은 여러 가지가 있지만 DROP문에서 부모 테이블의 항목 값을 삭제할 경우 자동적으로 자식 테이블의 해당 레코드를 삭제하기 위해서는 CASCADE 옵션을 사용합니다. CASCADE 옵션은 부모 테이블의 레코드가 삭제될 때 해당하는 자식 테이블의 레코드도 자동적으로 삭제되도록 하는 옵션입니다. 따라서 참조 무결성을 유지하기 위하여 DROP문에서 부모 테이블의 항목 값을 삭제할 경우 자동적으로 자식 테이블의 해당 레코드를 삭제하기 위한 옵션은 CASCADE입니다.</p>"]},"rate":78,"rateN":17038},{"id":"10640","number":55,"category":"데이터베이스 구축","type":"choice","subject":"DML에 해당하는 SQL 명령으로만 나열된 것은?","choices":[{"n":1,"html":"DELETE, UPDATE, CREATE, ALTER"},{"n":2,"html":"INSERT, DELETE, UPDATE, DROP"},{"n":3,"html":"SELECT, INSERT, DELETE, UPDATE"},{"n":4,"html":"SELECT, INSERT, DELETE, ALTER"}],"answer":[3],"wiki":[{"title":"SQL","url":"https://itwiki.kr/w/SQL"}],"explain":{"ai":["<p>DML은 데이터를 조작하는 언어를 말한다. DML에는 INSERT, UPDATE, DELETE 등이 있는데 이들은 데이터의 입력, 수정, 삭제를 의미한다. \nSELECT는 데이터를 조회하는 명령어로 DML에 해당한다. \n반면 CREATE와 ALTER는 테이블의 구조를 정의하거나 수정하는 명령어로 DDL에 해당하며 DROP은 테이블을 삭제하는 명령어로 DDL에 해당한다. \n따라서 DML에 해당하는 SQL 명령으로만 나열된 것은 3번의 SELECT, INSERT, DELETE, UPDATE이다.</p>"]},"rate":77,"rateN":16994},{"id":"10641","number":56,"category":"데이터베이스 구축","type":"choice","subject":"데이터 제어언어(DCL)의 기능으로 옳지 않은 것은?","choices":[{"n":1,"html":"데이터 보안"},{"n":2,"html":"논리적, 물리적 데이터 구조 정의"},{"n":3,"html":"무결성 유지"},{"n":4,"html":"병행수행 제어"}],"answer":[2],"wiki":[{"title":"SQL","url":"https://itwiki.kr/w/SQL"}],"explain":{"ai":["<p>데이터 제어언어는 데이터의 무결성과 일관성을 유지하고 데이터에 대한 접근을 제어하는 언어이다. \n데이터 제어언어의 기능은 데이터 보안, 무결성 유지, 병행수행 제어 등이 있다. \n논리적, 물리적 데이터 구조 정의는 데이터 정의어에서 담당하는 기능이다. \n따라서 데이터 제어언어의 기능으로 옳지 않은 것은 논리적, 물리적 데이터 구조 정의이다.</p>"]},"rate":62,"rateN":20407},{"id":"10643","number":57,"category":"데이터베이스 구축","type":"choice","subject":"병행제어의 로킹(Locking) 단위에 대한 설명으로 옳지 않은 것은?","choices":[{"n":1,"html":"데이터베이스, 파일, 레코드 등은 로킹 단위가 될 수 있다."},{"n":2,"html":"로킹 단위가 작아지면 로킹 오버헤드가 감소한다."},{"n":3,"html":"로킹 단위가 작아지면 데이터베이스 공유도가 증가한다."},{"n":4,"html":"한꺼번에 로킹 할 수 있는 객체의 크기를 로킹 단위라고 한다."}],"answer":[2],"wiki":[{"title":"데이터베이스 로킹","url":"https://itwiki.kr/w/데이터베이스 로킹"}],"explain":{"ai":["<p><strong>해설:</strong></p>\n<p>정답이 2번인 이유는 로킹 단위가 작아질수록 실제로는 로킹 오버헤드가 증가하기 때문입니다. </p>\n<ul>\n<li><strong>1번</strong>: 정확합니다. 실제로 데이터베이스, 파일, 레코드 등 다양한 수준에서 로킹이 이루어질 수 있습니다.</li>\n<li><strong>2번</strong>: <strong>오답</strong>입니다. 로킹 단위를 작게 설정하면 (예: 개별 레코드 단위), 더 많은 객체에 대한 잠금 관리가 필요해져 오버헤드가 증가합니다. 작은 단위로 로킹할수록 잠금 관리와 해제 과정이 복잡해져 시스템 부하가 커집니다.</li>\n<li><strong>3번</strong>: 정확합니다. 로킹 단위가 작아지면 더 세밀한 제어가 가능해져 동시에 여러 트랜잭션이 데이터베이스의 다른 부분을 공유하고 접근할 수 있는 기회가 늘어납니다.</li>\n<li><strong>4번</strong>: 정확한 정의입니다. 로킹 단위는 트랜잭션이 동시에 잠금을 걸 수 있는 데이터 객체의 크기를 의미합니다.</li>\n</ul>\n<p>따라서, 병행제어에서 로킹 오버헤드는 로킹 단위가 작아질수록 증가하는 것이 맞기 때문에 2번이 옳지 않은 설명입니다.</p>"]},"rate":70,"rateN":17400},{"id":"10642","number":58,"category":"데이터베이스 구축","type":"choice","subject":"E-R 모델의 표현 방법으로 옳지 않은 것은?","choices":[{"n":1,"html":"개체타입: 사각형"},{"n":2,"html":"관계타입: 마름모"},{"n":3,"html":"속성: 오각형"},{"n":4,"html":"연결: 선"}],"answer":[3],"wiki":[{"title":"ER 다이어그램","url":"https://itwiki.kr/w/ER 다이어그램"}],"explain":{"ai":["<p>E-R 모델은 데이터베이스 구축에서 사용되는 모델로 개체, 속성, 관계를 표시한다. \n개체타입은 사각형으로 표현하고 관계타입은 마름모로 표현하며 속성은 타원형으로 표현한다. \n목록에서 속성은 오각형으로 표시되어 있으므로 이는 옳지 않은 표현 방법이다.\n일반적으로 연결은 선으로 표시한다. \n즉 E-R 모델에서 속성은 일반적으로 타원형으로 표시하므로 3번이 정답이다.</p>"]},"rate":89,"rateN":14733},{"id":"10644","number":59,"category":"데이터베이스 구축","type":"choice","subject":"다음 설명의 (     )안에 들어갈 내용으로 적합한 것은?","extra":"<pre class=\"contents\">후보키는 릴레이션에 있는 모든 튜플에 대해 유일성과 (       )을 모두 만족시켜야 한다.</pre>","choices":[{"n":1,"html":"중복성"},{"n":2,"html":"최소성"},{"n":3,"html":"참조성"},{"n":4,"html":"동일성"}],"answer":[2],"wiki":[{"title":"데이터베이스 키","url":"https://itwiki.kr/w/데이터베이스 키"}],"explain":{"ai":["<p>후보키는 릴레이션에 있는 모든 튜플에 대해 유일성과 최소성을 모두 만족시켜야 한다. \n후보키의 특성은 튜플을 유일하게 식별할 수 있어야 하고, 속성의 부분집합이 될 수 없어야 한다. \n따라서 유일성은 각 튜플이 유일한 값을 가지고 있어야 함을 의미하고, 최소성은 후보키를 구성하는 속성의 부분집합이:key가 될 수 없어야 함을 의미한다. \n최소성은 즉,중복가 없어야 함을 뜻한다. \n중복성, 참조성, 동일성은 후보키의 특성이 아니다. \n중복성은 데이터베이스에서 데이터가 중복되어 저장되는 것을 의미하며, 참조성은 외래키의 특성이다. \n동일성은 데이터베이스에서 데이터의 일관성을 유지하는 것을 의미한다. \n하지만 후보키의 특성과는 관련이 없다. \n따라서 후보키는 유일성과 최소성을 만족시켜야 하며, 최적의 후보키를 선정하기 위해 정규화와정을 거쳐야 한다.</p>"]},"rate":74,"rateN":17398},{"id":"10645","number":60,"category":"데이터베이스 구축","type":"choice","subject":"정규화 과정 중 1NF에서 2NF가 되기 위한 조건은?","choices":[{"n":1,"html":"1NF를 만족하는 모든 도메인이 원자 값이어야 한다."},{"n":2,"html":"1NF를 만족하고 키가 아닌 모든 애트리뷰트들이 기본 키에 이행적으로 함수 종속되지 않아야 한다."},{"n":3,"html":"1NF를 만족하고 다치 종속이 제거되어야 한다."},{"n":4,"html":"1NF를 만족하고 키가 아닌 모든 속성이 기본키에 대하여 완전 함수적 종속 관계를 만족해야 한다."}],"answer":[4],"explain":{"ai":["<p>1NF에서 2NF로 정규화하기 위해서는 1NF를 만족하고 키가 아닌 모든 속성이 기본키에 대하여완전 함수적 종속 관계를 만족해야 한다. 이는 부분 함수적 종속성 제거를 통해 데이터의 일관성과 무결성을 높이고, 데이터의 중복을 최소화하기 위함이다. 따라서 1NF를 만족하는 테이블에서 기본키가 복합키인 경우, 기본키가 아닌 모든 속성들이 기본키 전체에 함수적으로 종속되는지를 확인해야 한다.</p>"]},"rate":55,"rateN":22510},{"id":"10646","number":61,"category":"프로그래밍 언어 활용","type":"choice","subject":"IPv6에 대한 설명으로 틀린 것은?","choices":[{"n":1,"html":"128비트의 주소 공간을 제공한다."},{"n":2,"html":"인증 및 보안 기능을 포함하고 있다."},{"n":3,"html":"패킷 크기가 64Kbyte로 고정되어 있다."},{"n":4,"html":"IPv6 확장 헤더를 통해 네트워크 기능 확장이 용이하다."}],"answer":[3],"wiki":[{"title":"IPv6","url":"https://itwiki.kr/w/IPv6"}],"explain":{"ai":["<p>IPv6는 기존 IPv4의 주소 공간 제한과 보안 문제를 해결하기 위해 개발됨. IPv6의 주소 공간은 128비트로, 매우 큰 주소 공간을 제공함. 또한, 인증 및 보안 기능을 포함하고 있으며, IPv6 확장 헤더를 통해 네트워크 기능 확장이 용이함. </p>\n<p>하지만, IPv6의 패킷 크기는 최대 64KB이지만, 고정되어 있지 않음. IPv6의 패킷 크기는 MTU(Maximum Transmission Unit)로 정의되며, 네트워크 환경에 따라 다를 수 있음. 따라서, 3번 항목이 틀린 설명임.</p>"]},"rate":80,"rateN":16762},{"id":"10647","number":62,"category":"프로그래밍 언어 활용","type":"choice","subject":"C언어에서 비트 논리연산자에 해당하지 않는 것은?","choices":[{"n":1,"html":"^"},{"n":2,"html":"?"},{"n":3,"html":"&"},{"n":4,"html":"~"}],"answer":[2],"wiki":[{"title":"BIT 연산","url":"https://itwiki.kr/w/BIT 연산"}],"explain":{"ai":["<p>C언어에서 비트 논리연산자는 비트 단위로 논리 연산을 수행하는 연산자입니다. \n비트 논리연산자는 두 개의 비트를 비교하여 결과를 반환합니다. \n'^'는 배타적 논리합을 의미하고 '&amp;'는 비트 논리곱을 의미합니다. \n'~'는 비트 논리부정을 의미합니다. \n'?', 즉 물음표는 비트 논리연산자가드레스 않으며, 조건 연산자로 사용됩니다. \n조건 연산자는 세 개의 피연산자를 가지는 연산자로, 특정 조건에 따라 값을 선택합니다. \n따라서 조건 연산자로 사용되는 '?'는 비트 논리연산자가 아니므로 정답은 2번입니다.</p>"]},"rate":63,"rateN":20077},{"id":"10648","number":63,"category":"프로그래밍 언어 활용","type":"choice","subject":"TCP/IP 프로토콜 중 전송계층 프로토콜은?","choices":[{"n":1,"html":"HTTP"},{"n":2,"html":"SMTP"},{"n":3,"html":"FTP"},{"n":4,"html":"TCP"}],"answer":[4],"wiki":[{"title":"TCP/IP","url":"https://itwiki.kr/w/TCP/IP"},{"title":"SMTP","url":"https://itwiki.kr/w/SMTP"}],"explain":{"ai":["<p>전송계층 프로토콜은 데이터를 신뢰성 있게 전달하는 역할을 한다. TCP/IP 프로토콜 중 전송계층 프로토콜은 TCP와 UDP가 있다. TCP는 연결형 프로토콜로 데이터를 전달할 때 연결을 설정하고 종료하는 과정을 거치며, 데이터의 순차적 전달과 재전송을 담당한다. 반면에 UDP는 비연결형 프로토콜로 연결 설정 없이 데이터를 전달하며, 순차적 전달이나 재전송을 보장하지 않는다. </p>\n<p>HTTP, SMTP, FTP는 응용계층 프로토콜로, TCP/IP 프로토콜 중 전송계층 프로토콜이 아니다. 따라서 전송계층 프로토콜은 TCP가 정답이다.</p>"]},"rate":65,"rateN":19673},{"id":"10649","number":64,"category":"프로그래밍 언어 활용","type":"choice","subject":"시스템에서 모듈 사이의 결합도(Coupling)에 대한 설명으로 옳은 것은?","choices":[{"n":1,"html":"한 모듈 내에 있는 처리요소들 사이의 기능적인 연관 정도를 나타낸다."},{"n":2,"html":"결합도가 높으면 시스템 구현 및 유지보수 작업이 쉽다."},{"n":3,"html":"모듈간의 결합도를 약하게 하면 모듈 독립성이 향상된다."},{"n":4,"html":"자료결합도는 내용결합도 보다 결합도가 높다."}],"answer":[3],"wiki":[{"title":"결합도","url":"https://itwiki.kr/w/결합도"}],"explain":{"ai":["<p>결합도는 모듈 간의 상호 의존성을 측정하는 지표이다. 올바른 설명은 다음과 같다:</p>\n<ol>\n<li>한 모듈 내의 내부 요소들 간의 연관성을 설명하므로, 이는 내부 응집도(Cohesion)와 관련이 있어 결합도에 대한 설명이 아니다.</li>\n<li>결합도가 높을수록 모듈 간 의존성이 커져 시스템의 구현과 유지보수가 어려워진다. 따라서 이 설명은 틀렸다.</li>\n<li>정답이다. 모듈 간의 결합도를 낮추면 각 모듈이 독립적으로 작동할 수 있어 재사용성과 유지보수성이 향상된다.</li>\n<li>사실과 반대다. 내용결합도는 모듈이 다른 모듈의 내부 데이터에 직접 접근하므로 가장 높은 수준의 결합도를 나타내며, 자료결합도는 매개변수를 통해 데이터를 주고받으므로 내용결합도보다 결합도가 낮다.</li>\n</ol>\n<p>따라서 옳은 설명은 3번이다.</p>"]},"rate":67,"rateN":18788},{"id":"10650","number":65,"category":"프로그래밍 언어 활용","type":"choice","subject":"은행가 알고리즘(Banker's Algorithm)은 교착상태의 해결 방법 중 어떤 기법에 해당하는가?","choices":[{"n":1,"html":"Avoidance"},{"n":2,"html":"Detection"},{"n":3,"html":"Prevention"},{"n":4,"html":"Recovery"}],"answer":[1],"wiki":[{"title":"교착상태","url":"https://itwiki.kr/w/교착상태"}],"explain":{"ai":["<p>은행가 알고리즘은 교착상태를 회피하는 방법인 Avoidance에 해당한다. 은행가 알고리즘은 프로세스가 자원을 요구할 때 시스템이 자원을 할당하여도 안전한 상태로 남아 있는지 확인하고, 안전한 상태라면 자원을 할당하고, 안정하지 않은 상태라면 자원을 할당하지 않는 방식으로 작동한다. 이렇게 하면 시스템이 교착상태에 빠지는 것을 피할 수 있다._Tis 방식은 교착상태가 발생하지 않도록 미리 예방하고 회피하는 전략에 해당한다.</p>"]},"rate":65,"rateN":18691},{"id":"10651","number":66,"category":"프로그래밍 언어 활용","type":"choice","subject":"UNIX의 쉘(Shell)에 관한 설명으로 옳지 않은 것은?","choices":[{"n":1,"html":"명령어 해석기이다."},{"n":2,"html":"시스템과 사용자 간의 인터페이스를 담당한다."},{"n":3,"html":"여러 종류의 쉘이 있다."},{"n":4,"html":"프로세스, 기억장치, 입출력 관리를 수행한다."}],"answer":[4],"explain":{"ai":["<p>UNIX의 쉘은 사용자와 시스템 간의 인터페이스 역할을 하며, 사용자의 명령어를 해석하고 실행하는 명령어 해석기이다. 여러 종류의 쉘이 있opensourceStraingt Bash, C 쉘 등이 있으며, 각 쉘은 자신의 장단점을 가지고 있다. 그러나 프로세스, 기억장치, 입출력 관리는 운영체제의 커널이 담당한다. 따라서 프로세스, 기억장치, 입출력 관리를 수행한다는 것은 쉘의 역할이 아니다.</p>"]},"rate":62,"rateN":19831},{"id":"10652","number":67,"category":"프로그래밍 언어 활용","type":"choice","subject":"교착 상태 발생의 필요 충분 조건이 아닌 것은?","choices":[{"n":1,"html":"상호 배제(mutual exclusion)"},{"n":2,"html":"점유와 대기(hold and wait)"},{"n":3,"html":"환형 대기(circular wait)"},{"n":4,"html":"선점(preemption)"}],"answer":[4],"wiki":[{"title":"교착상태","url":"https://itwiki.kr/w/교착상태"}],"explain":{"ai":["<p>교착 상태 발생의 필요 충분 조건은 상호 배제, 점유와 대기, 환형 대기가 모두 만족할 때 발생한다. 선점은 교착 상태를 방지하기 위한 조건 중 하나로, 교착 상태 발생의 필요 충분 조건이 아니다. 선점이란 한 프로세스가 다른 프로세스에 할당된 자원을 강제로 취득하는 것을 말한다. 이는 교착 상태를 예방또는 회피하기 위한 방법 중 하나로 사용된다. 따라서 교착 상태 발생의 필요 충분 조건이 아닌 것은 선점이다.</p>"]},"rate":62,"rateN":19697},{"id":"10653","number":68,"category":"프로그래밍 언어 활용","type":"choice","subject":"OSI-7계층에서 종단간 신뢰성 있고 효율적인 데이터를 전송하기 위해 오류검출과 복구, 흐름 제어를 수행하는 계층은?","choices":[{"n":1,"html":"전송 계층"},{"n":2,"html":"세션 계층"},{"n":3,"html":"표현 계층"},{"n":4,"html":"응용 계층"}],"answer":[1],"wiki":[{"title":"OSI 7계층","url":"https://itwiki.kr/w/OSI 7계층"}],"explain":{"ai":["<p>OSI 7계층은 네트워크 통신을 위해서 필요한 계층으로 각각의 계층을 통해 데이터를 전송할 때 특정한 기능을 수행한다. </p>\n<p>계층 중 전송 계층은 종단 간 신뢰성 있고 효율적인 데이터 전송을 위해 필요한 기능을 제공한다. 이 계층은 오류 검출과 복구, 흐름 제어 등과 같은 기능을 수행하여 데이터 전송의 안정성과 신뢰성을 보장한다. </p>\n<p>전송 계층은 오류가 발생했을 때 해당 데이터를 다시 전송하여 데이터의 완전성을 유지할 수 있도록 하며, 또한 흐름 제어를 통해 네트워크의 혼잡을 방지하고 데이터 전송 속도를 조절할 수 있다. </p>\n<p>따라서 전송 계층은 종단 간 신뢰성 있고 효율적인 데이터 전송을 위해 오류 검출과 복구, 흐름 제어 등의 기능을 수행하는 계층이다.</p>"]},"rate":71,"rateN":18510},{"id":"10654","number":69,"category":"프로그래밍 언어 활용","type":"choice","subject":"IPv6의 주소체계로 거리가 먼 것은?","choices":[{"n":1,"html":"Unicast"},{"n":2,"html":"Anycast"},{"n":3,"html":"Broadcast"},{"n":4,"html":"Multicast"}],"answer":[3],"wiki":[{"title":"IPv6","url":"https://itwiki.kr/w/IPv6"}],"explain":{"ai":["<p>IPv6 주소 체계에서 Broadcast는 전통적인 IPv4에서 주로 사용되던 일대다 통신 방식으로, 네트워크 내 모든 장치에 패킷을 보내는 기능을 담당했습니다. 그러나 보안과 효율성 측면에서 문제점이 있어 IPv6에서는 이 개념을 다르게 처리하거나 제한적으로 사용합니다. 대신, IPv6는 특정 그룹에게 메시지를 보내는 Multicast나 여러 개의 특정 대상에게 각각 개별적으로 패킷을 전송하는 Unicast, 그리고 여러 노드 중 가장 가까운 하나에게 패킷을 전달하는 Anycast와 같은 방식을 강조합니다. 따라서 주어진 보기 중 IPv6의 설계 철학과 맞지 않는 것은 Broadcast(3번)입니다.</p>"]},"rate":64,"rateN":19049},{"id":"10655","number":70,"category":"프로그래밍 언어 활용","type":"choice","subject":"TCP/IP 네트워크에서 IP 주소를 MAC 주소로 변환하는 프로토콜은?","choices":[{"n":1,"html":"UDP"},{"n":2,"html":"ARP"},{"n":3,"html":"TCP"},{"n":4,"html":"ICMP"}],"answer":[2],"wiki":[{"title":"ARP","url":"https://itwiki.kr/w/ARP"}],"explain":{"ai":["<p>컴퓨터 네트워크에서 통신을 하기 위해선 IP 주소와 MAC 주소를 정확하게 매핑해줘야 해. IP 주소를 MAC 주소로 변환해주는 프로토콜이 바로 ARP야. ARP는 Address Resolution Protocol의 약자로, IP 주소를 MAC 주소로 변환해줘. 네트워크 상에 있는 장치들의 IP 주소와 MAC 주소를 서로 변환해서 맞춰주는 역할을 해. UDP, TCP, ICMP는 모두 다른 목적을 가진 프로토콜이라 IP 주소를 MAC 주소로 변환하는 데 사용되지는 않아. 따라서 정답은 ARP인 2번이야.</p>"]},"rate":62,"rateN":21149},{"id":"10656","number":71,"category":"프로그래밍 언어 활용","type":"choice","subject":"프로세스 상태의 종류가 아닌 것은?","choices":[{"n":1,"html":"Ready"},{"n":2,"html":"Running"},{"n":3,"html":"Requst"},{"n":4,"html":"Exit"}],"answer":[3],"wiki":[{"title":"프로세스 상태","url":"https://itwiki.kr/w/프로세스 상태"}],"explain":{"ai":["<p>프로세스 상태의 종류는 다음과 같다. \n대기 상태, 준비 상태, 실행 상태, 종료 상태가 있다. \n여기서 실행 상태는 Running, 대기 상태는 Wait, 준비 상태는 Ready, 종료 상태는 Exit와 같은 의미라고 볼 수 있다. \n즉, 프로세스 상태의 종류는 Ready, Running, Wait, Exit이다. \nWait를 Request라고 잘못 표기한 경우가 많다. \n그러므로 프로세스 상태의 종류가 아닌 것은 Request이다. \n따라서 정답은 3번이다.</p>"]},"rate":67,"rateN":18495},{"id":"10657","number":72,"category":"프로그래밍 언어 활용","type":"choice","subject":"스레드(Thread)에 대한 설명으로 옳지 않은 것은?","choices":[{"n":1,"html":"한 개의 프로세스는 여러 개의 스레드를 가질 수 없다."},{"n":2,"html":"커널 스레드의 경우 운영체제에 의해 스레드를 운용한다."},{"n":3,"html":"사용자 스레드의 경우 사용자가 만든 라이브러리를 사용하여 스레드를 운용한다."},{"n":4,"html":"스레드를 사용함으로써 하드웨어, 운영체제의 성능과 응용 프로그램의 처리율을 향상시킬 수 있다."}],"answer":[1],"wiki":[{"title":"스레드","url":"https://itwiki.kr/w/스레드"}],"explain":{"ai":["<p>스레드는 프로세스 내에서 실행되는 독립적인 실행 단위다. 하나의 프로세스는 여러개의 스레드를 가질 수 있다. 스레드들은 프로세스의 자원을 공유하며 각 스레드는자신의 프로그램 카운터,자신의 레지스터들을 가지고 있다.</p>\n<p>운영체제는 프로세스와 스레드라는 두 가지 개념을 제공한다. 프로세스는 운영체제가 관리하는 실행 단위이며 스레드는 프로세스 내에서 실행되는 더 작은 실행 단위다. </p>\n<p>커널 스레드는 사용자 레벨에서 스레드를 관리하는 사용자 스레드와 달리 운영체제 내부에서 스레드를 관리한다. 사용자 스레드는 사용자가 만든 라이브러리를 사용하여 스레드를 관리한다. </p>\n<p>스레드를 사용하면 하드웨어와 운영체제의 성능을 향상시키고 응용 프로그램의 처리율을 높일 수 있다. 스레드를 사용하면 여러 작업을 동시에 수행할 수 있기 때문에 시스템의 전체적인 성능을 향상시킬 수 있다. </p>\n<p>따라서 1번이 정답이다. 한 개의 프로세스는 여러 개의 스레드를 가질 수 있다.</p>"]},"rate":77,"rateN":17069},{"id":"10658","number":73,"category":"프로그래밍 언어 활용","type":"choice","subject":"HRN(Highest Response-ratio Next) 스케줄링 방식에 대한 설명으로 옳지 않은 것은?","choices":[{"n":1,"html":"대기 시간이 긴 프로세스의 경우 우선 순위가 높아진다."},{"n":2,"html":"SJF 기법을 보완하기 위한 방식이다."},{"n":3,"html":"긴 작업과 짧은 작업 간의 지나친 불평등을 해소할 수 있다."},{"n":4,"html":"우선 순위를 계산하여 그 수치가 가장 낮은 것부터 높은 순으로 우선 순위가 부여된다."}],"answer":[4],"wiki":[{"title":"HRRN_스케줄링","url":"https://itwiki.kr/w/HRRN_스케줄링"}],"explain":{"ai":["<p>HRN 스케줄링 방식은 대기 시간이 긴 프로세스에 우선 순위를 높여 주어 SJF 기법의 단점을 보완하는 방식이다. HRN 스케줄링은 각 프로세스의 우선 순위를 계산하여 그 수치가 가장 높은 것부터 낮은 순으로 우선 순위가 부여된다. 따라서 4번이 옳지 않은 설명이다. HRN 스케줄링은 대기 시간이 긴 프로세스에 높은 우선 순위를 부여하여 긴 작업과 짧은 작업 간의 불평등을 줄인다. 또한 SJF 기법의 단점을 보완하여 더 나은 스케줄링을 제공한다.</p>"]},"rate":66,"rateN":18797},{"id":"10659","number":74,"category":"프로그래밍 언어 활용","type":"choice","subject":"IEEE 802.11 워킹 그룹의 무선 LAN 표준화 현황 중 QoS 강화를 위해 MAC 지원 가능을 채택한 것은?","choices":[{"n":1,"html":"802.22a"},{"n":2,"html":"802.11b"},{"n":3,"html":"802.11g"},{"n":4,"html":"802.11e"}],"answer":[4],"explain":{"ai":["<p>IEEE 802.11 워킹 그룹의 무선 LAN 표준화 현황 중 QoS 강화를 위해 MAC 지원 가능을 채택한 것은 802.11e이다. 802.11e는 기존의 무선 LAN 표준에 추가적인 기능을 제공하여 음성 및 비디오와 같은 실시간 트래픽에 대한 지원을 강화한다. 이는 MAC 계층에서 품질 보증을 제공하도록 설계되어가 있 mediaPlayer나 화상 회의와 같은 서비스 품질을 보장하는데 필수적이다. 이러한 기능으로 인해 802.11e는 무선 네트워크에서 품질 보증 지원이가 필요한 다양한 애플리케이션을 지원하는데 사용된다.</p>"]},"rate":60,"rateN":19386},{"id":"10660","number":75,"category":"프로그래밍 언어 활용","type":"choice","subject":"C언어에서 사용할 수 없는 변수명은?","choices":[{"n":1,"html":"student2019"},{"n":2,"html":"text-color"},{"n":3,"html":"_korea"},{"n":4,"html":"amount"}],"answer":[2],"wiki":[{"title":"c언어 변수 규칙","url":"https://itwiki.kr/w/c언어 변수 규칙"}],"explain":{"ai":["<p>C언어에서 변수명을 정의할 때 특정 규칙을 따라야 한다. 변수명은 영문자, 숫자, 언더바로 구성할 수 있다. 하지만 변수명의 첫 글자는 숫자가 될 수 없다. </p>\n<p>문자와 숫자를 조합하거나 언더바를 사용하는 것은 가능하다. 예를 들어 student2019, _korea, amount와 같은 변수명은 모두 허용된다. </p>\n<p>그러나 변수명에 하이픈을 포함할 수는 없다. 따라서 text-color와 같은 변수명은 사용할 수 없다. 이것이 문제에서 변수명으로 사용할 수 없는 예이다.</p>"]},"rate":66,"rateN":19606},{"id":"10661","number":76,"category":"프로그래밍 언어 활용","type":"choice","subject":"스크립트 언어가 아닌 것은?","choices":[{"n":1,"html":"PHP"},{"n":2,"html":"Cobol"},{"n":3,"html":"Basic"},{"n":4,"html":"Python"}],"answer":[2],"wiki":[{"title":"스크립트 언어","url":"https://itwiki.kr/w/스크립트 언어"}],"explain":{"ai":["<p>스크립트 언어는 컴퓨터 프로그램을 작성할 때 사용되는 프로그래밍 언어의 한 종류로, 주로 웹 개발이나 빠른 프로그래밍에 사용된다. 옵션 중에서 PHP, Basic, Python은 전형적인 스크립트 언어의 특성을 가지고 있다. </p>\n<p>반면에 Cobol은 고급 언어로, 주로 대형 컴퓨터에서 상업용 프로그램을 개발하는 데 사용되었다. Cobol은 스크립트 언어가 아니며, 컴파일 언어로 분류된다. 즉, Cobol은 소스 코드를 기계어로 컴파일한 후 실행하는 반면, 스크립트 언어는 인터프리터 또는 바이트 코드를 통해서 실행된다. 따라서 스크립트 언어가 아닌 것은 Cobol이다.</p>"]},"rate":59,"rateN":21104},{"id":"10662","number":77,"category":"프로그래밍 언어 활용","type":"choice","subject":"다음의 페이지 참조 열(Page reference string)에 대해 페이지 교체 기법으로 선입선출 알고리즘을 사용할 경우 페이지 부재(Page Fault) 횟수는? (단, 할당된 페이지 프레임 수는 3이고, 처음에는 모든 프레임이 비어 있다.)","extra":"<pre class=\"contents\">7, 0, 1, 2, 0, 3, 0, 4, 2, 3, 0, 3, 2, 1, 2, 0, 1, 7, 0</pre>","choices":[{"n":1,"html":"13"},{"n":2,"html":"14"},{"n":3,"html":"15"},{"n":4,"html":"20"}],"answer":[2],"wiki":[{"title":"페이지 교체","url":"https://itwiki.kr/w/페이지 교체"}],"explain":{"ai":["<p>선입선출 알고리즘은 페이지 교체 기법 중 하나로, 가장 먼저 들어온 페이지를 가장 먼저 교체하는 방식입니다. 이 알고리즘은 페이지 참조열과 할당된 페이지 프레임 수를 기준으로 페이지 부재 횟수를 결정합니다.</p>\n<p>페이지 참조열은 7, 0, 1, 2, 0, 3, 0, 4, 2, 3, 0, 3, 2, 1, 2, 0, 1, 7, 0입니다. 할당된 페이지 프레임 수는 3이고, 처음에는 모든 프레임이 비어 있습니다.</p>\n<p>선입선출 알고리즘을 적용하여 페이지 부재 횟수를 계산하면 다음과 같습니다. </p>\n<p>-pages 7, 0, 1이 들어오면서 page fault가 발생합니다. </p>\n<ul>\n<li>pages 2가 들어오면서 page fault가 발생하고, 7이 교체됩니다. </li>\n<li>pages 0이 이미 있기 때문에 page fault가 발생하지 않습니다.</li>\n<li>pages 3이 들어오면서 page fault가 발생하고, 1이 교체됩니다.</li>\n<li>pages 0이 이미 있기 때문에 page fault가 발생하지 않습니다.</li>\n<li>pages 4가 들어오면서 page fault가 발생하고, 0이 교체됩니다.</li>\n<li>pages 2가 이미 있기 때문에 page fault가 발생하지 않습니다.</li>\n<li>pages 3이 이미 있기 때문에 page fault가 발생하지 않습니다.</li>\n<li>pages 0이 들어오면서 page fault가 발생하고, 4가 교체됩니다.</li>\n<li>pages 3이 이미 있기 때문에 page fault가 발생하지 않습니다.</li>\n<li>pages 2가 이미 있기 때문에 page fault가 발생하지 않습니다.</li>\n<li>pages 1이 들어오면서 page fault가 발생하고, 3이 교체됩니다.</li>\n<li>pages 2가 이미 있기 때문에 page fault가 발생하지 않습니다.</li>\n<li>pages 0이 들어오면서 page fault가 발생하고, 1이 교체됩니다.</li>\n<li>pages 1이 들어오면서 page fault가 발생하고, 2가 교체됩니다.</li>\n<li>pages 7이 들어오면서 page fault가 발생하고, 0이 교체됩니다.</li>\n<li>pages 0이 들어오면서 page fault가 발생하고, 7이 교체됩니다.</li>\n</ul>\n<p>따라서 총 페이지 부재 횟수는 14입니다.</p>"]},"rate":62,"rateN":16455},{"id":"10663","number":78,"category":"프로그래밍 언어 활용","type":"choice","subject":"C언어에서 배열 b[5]의 값은?","extra":"<pre class=\"contents\">static int b[9]={1, 2, 3};</pre>","choices":[{"n":1,"html":"0"},{"n":2,"html":"1"},{"n":3,"html":"2"},{"n":4,"html":"3"}],"answer":[1],"explain":{"ai":["<p>C언어에서 배열은 0번째 인덱스부터 시작한다. \n배열 b는 static int b[9]={1, 2, 3}; 로 선언되어 있다. \n여기서 9는 배열의 크기이며, 초기값은 1, 2, 3이다. \n배열의 크기는 9지만 초기값은 3개만 주어졌으므로 나머지 요소들은 0으로 초기화된다. \n배열 b의 5번째 요소의 인덱스는 4이며, 초기값이 주어지지 않았으므로 0으로 초기화된다. \n따라서 배열 b[5]의 값은 0이다.</p>"]},"rate":77,"rateN":16106},{"id":"10664","number":79,"category":"프로그래밍 언어 활용","type":"choice","subject":"응집도가 가장 낮은 것은?","choices":[{"n":1,"html":"기능적 응집도"},{"n":2,"html":"시간적 응집도"},{"n":3,"html":"절차적 응집도"},{"n":4,"html":"우연적 응집도"}],"answer":[4],"wiki":[{"title":"응집도","url":"https://itwiki.kr/w/응집도"}],"explain":{"ai":["<p>응집도는 모듈 내부 요소들이 서로 얼마나 잘 연관되어 있는지 측정하는지표이다. 응집도가 높은 모듈은 하나의 기능을 수행하기 위해 서로 긴밀하게 관련된 요소들로 연결되어 있다. </p>\n<p>다음은 응집도의 종류들이다. \n기능적 응집도는 모듈이 하나의 기능을 수행하는 단위로 구성된 경우이다. \n시간적 응집도는 특정 시간에 수행되는 코드들을 모은 경우이다. \n절차적 응집도는 몇 가지 관련된 절차로 이루어진 경우이다. \n우연적 응집도는 서로 관련이 없는 코드들이 모인 경우로 모듈 내부 요소들이 서로 무관하게 흩어져 있는 경우이다. </p>\n<p>우연적 응집도는 아무런 논리적관련이 없는 코드들이 함께 모여있기 때문에 응집도가 가장 낮다. 그러므로 우연적 응집도가 가장 낮은 응집도라 할 수 있다.</p>"]},"rate":87,"rateN":15174},{"id":"10665","number":80,"category":"프로그래밍 언어 활용","type":"choice","subject":"JAVA 언어에서 접근제한자가 아닌 것은?","choices":[{"n":1,"html":"public"},{"n":2,"html":"protected"},{"n":3,"html":"package"},{"n":4,"html":"private"}],"answer":[3],"explain":{"ai":["<p>JAVA 언어에서 접근제한자는 클래스나 메서드, 변수의 accessibility를 결정한다. \n접근제한자에는 public, protected, private가 있다. \npublic은 모든 곳에서 접근이 가능하고, \nprotected는 같은 패키지나 상속받은 클래스에서 접근이 가능하다. \nprivate는 같은 클래스에서만 접근이 가능하다. \n하지만 package는 접근제한자가 아닌 default 접근 지정자로, \n별도로 접근제한자를 지정하지 않았을 때의 기본값이다. \n따라서 JAVA 언어에서 접근제한자가 아닌 것은 package이다. \n그러므로 정답은 3번이다.</p>"]},"rate":78,"rateN":16534},{"id":"10666","number":81,"category":"정보시스템 구축관리","type":"choice","subject":"Rayleigh-Norden 곡선의 노력 분포도를 이용한 프로젝트 비용 산정기법은?","choices":[{"n":1,"html":"Putnam 모형"},{"n":2,"html":"델파이 모형"},{"n":3,"html":"COCOMO 모형"},{"n":4,"html":"기능점수 모형"}],"answer":[1],"explain":{"ai":["<p>Putnam 모형은 Rayleigh-Norden 곡선의 노력 분포도를 이용한 프로젝트 비용 산정기법입니다. 이 모형은 프로젝트의 노력을 시간에 따라 계산하여 비용을 산정하는 방법입니다. Rayleigh-Norden 곡선은 프로젝트의 노력 분포를 나타내는 곡선으로, 프로젝트의 초기와 말기에 노력이 집중되는 경향을 보여줍니다. Putnam 모형은 이 곡선을 이용하여 프로젝트의 총 노력과 비용을 산정합니다.</p>"]},"rate":56,"rateN":22421},{"id":"10667","number":82,"category":"정보시스템 구축관리","type":"choice","subject":"메모리상에서 프로그램의 복귀 주소와 변수사이에 특정 값을 저장해 두었다가 그 값이 변경되었을 경우 오버플로우 상태로 가정하여 프로그램 실행을 중단하는 기술은?","choices":[{"n":1,"html":"모드체크"},{"n":2,"html":"리커버리 통제"},{"n":3,"html":"시스로그"},{"n":4,"html":"스택가드"}],"answer":[4],"wiki":[{"title":"버퍼 오버플로우","url":"https://itwiki.kr/w/버퍼 오버플로우"}],"explain":{"ai":["<p>스택 가드는 메모리상에서 프로그램의 복귀 주소와 변수 사이에 특정 값을 저장해 두었다가 그 값이 변경되었을 경우 오버플로우 상태로 가정하여 프로그램 실행을 중단하는 기술입니다. 이는 버퍼 오버플로우와 같은 공격으로부터 프로그램을 보호하기 위한 보안 메커니즘 중 하나입니다. 스택 가드가 활성화되면 프로그램의 스택 영역에 특정한 가드 값이 삽입되고 이는 함수 호출 시에 복귀 주소와 변수 사이에 위치합니다. 만약 공격자가 버퍼 오버플로우를 이용하여 이 가드 값을 변경하려고 하면 프로그램은 오버플로우를 감지하고 즉시 실행을 중단하여 추가적인 피해를 막을 수 있습니다. 이러한 기법은 프로그램의 안정성과 보안성을 향상시키는 데 중요한 역할을 합니다.</p>"]},"rate":75,"rateN":16533},{"id":"10668","number":83,"category":"정보시스템 구축관리","type":"choice","subject":"백도어 탐지 방법으로 틀린 것은?","choices":[{"n":1,"html":"무결성 검사"},{"n":2,"html":"닫힌 포트 확인"},{"n":3,"html":"로그 분석"},{"n":4,"html":"SetUID 파일 검사"}],"answer":[2],"explain":{"ai":["<p>백도어 탐지 방법으로는 무결성 검사, 로그 분석, SetUID 파일 검사를 사용합니다. </p>\n<p>닫힌 포트 확인은 백도어 탐지와 직접적인 관련이 없습니다. 포트 확인은 네트워크 보안에서 개방되어 있는 포트를 확인하여 불필요한 개방 포트를 닫아 보안을 강화하는 방법이며, 백도어 자체를 탐지하는 방법은 아닙니다. </p>\n<p>따라서 백도어 탐지 방법으로는 틀린 것이 닫힌 포트 확인입니다.</p>"]},"rate":63,"rateN":18287},{"id":"10669","number":84,"category":"정보시스템 구축관리","type":"choice","subject":"IP 또는 ICMP의 특성을 악용하여 특정 사이트에 집중적으로 데이터를 보내 네트워크 또는 시스템의 상태를 불능으로 만드는 공격 방법은?","choices":[{"n":1,"html":"TearDrop"},{"n":2,"html":"Smishing"},{"n":3,"html":"Qshing"},{"n":4,"html":"Smurfing"}],"answer":[4],"wiki":[{"title":"스머프 공격","url":"https://itwiki.kr/w/스머프 공격"}],"explain":{"ai":["<p>Smurfing 공격은 ICMP(인터넷 제어 메시지 프로토콜)의 특성을 악용하는 방법입니다. 공격자가 특정 타겟 네트워크나 시스템의 IP 주소 대신 그 네트워크의 브로드캐스트 주소나 무작위 IP 주소로 ICMP Echo Request 패킷을 대량으로 발송합니다. 이 패킷들은 네트워크 내 모든 호스트에게 응답을 요구하게 되어, 실제로 목표로 삼은 시스템뿐만 아니라 네트워크 전체의 장비들이 과도한 응답 패킷을 생성하게 됩니다. 이로 인해 네트워크 트래픽이 폭발적으로 증가하여 정상적인 네트워크 및 시스템 작동이 불가능해질 수 있습니다. 다른 옵션들인 TearDrop은 패킷 재조립 관련 취약점 공격, Smishing과 Phishing은 각각 문자메시지와 피싱 이메일을 통한 사기 공격으로, 주어진 문제의 공격 유형과는 관련이 없습니다. 따라서 정답은 4번 Smurfing입니다.</p>"]},"rate":67,"rateN":18350},{"id":"10670","number":85,"category":"정보시스템 구축관리","type":"choice","subject":"CMM(Capability Maturity Model) 모델의 레벨로 옳지 않은 것은?","choices":[{"n":1,"html":"최적단계"},{"n":2,"html":"관리단계"},{"n":3,"html":"정의단계"},{"n":4,"html":"계획단계"}],"answer":[4],"wiki":[{"title":"CMMi","url":"https://itwiki.kr/w/CMMi"}],"explain":{"ai":["<p>정답은 4번입니다. CMM 모델은 소프트웨어 개발 및 관리 프로세스의 성숙도를 5단계로 구분합니다. 각 레벨은 다음과 같습니다:</p>\n<ol>\n<li><strong>초기단계 (Initial)</strong>: 프로세스가 임의적이고 예측 불가능한 상태.</li>\n<li><strong>정의단계 (Managed)</strong>: 프로세스가 일부 정의되어 관리되지만 일관성이 부족.</li>\n<li><strong>관리단계 (Defined)</strong>: 조직 전체에 걸쳐 표준화된 프로세스가 정립되어 있음.</li>\n<li><strong>확립단계 (Quantitatively Managed)</strong>: 프로세스 성능이 정량적으로 측정되고 개선됨.</li>\n<li><strong>최적단계 (Optimizing)</strong>: 지속적인 개선을 통해 최적의 성과를 추구.</li>\n</ol>\n<p>보기 중 '계획단계'는 CMM 모델의 정식 분류에 포함되지 않습니다. 따라서 옳지 않은 레벨은 4번 '계획단계'입니다.</p>"]},"rate":50,"rateN":23081},{"id":"10671","number":86,"category":"정보시스템 구축관리","type":"choice","subject":"웹과 컴퓨터 프로그램에서 용량이 적은 데이터를 교환하기 위해 데이터 객체를 속성·값의 쌍 형태로 표현하는 형식으로 자바스크립트(JavaScript)를 토대로 개발되어진 형식은?","choices":[{"n":1,"html":"Python"},{"n":2,"html":"XML"},{"n":3,"html":"JSON"},{"n":4,"html":"WEB SEVER"}],"answer":[3],"wiki":[{"title":"JSON","url":"https://itwiki.kr/w/JSON"}],"explain":{"ai":["<p>웹과 컴퓨터 프로그램에서 데이터를 교환할 때 용량이 적은 데이터를 다룰 수 있는 형식은 JSON이다. JSON은 자바스크립트를 토대로 개발되어서 용량이 작고 가볍기 때문에 데이터 교환에 많이 사용된다. </p>\n<p>JSON은 속성과 값의 쌍 형태로 데이터를 표현하기 때문에 쉽게 데이터를 이해하고 처리할 수 있다. 따라서 JSON은 웹과 컴퓨터 프로그램에서 데이터를 교환할 때 많이 사용되는 형식이다. </p>\n<p>다른 형식인 XML도 데이터를 교환할 때 사용되지만 XML은 태그를 사용하기 때문에 용량이 더 크고 복잡할 수 있다. 반면에 JSON은 간단하고 가벼워서 데이터 교환에 많이 사용된다. </p>\n<p>따라서 정답은 JSON이다.</p>"]},"rate":86,"rateN":14859},{"id":"10672","number":87,"category":"정보시스템 구축관리","type":"choice","subject":"크래커가 침입하여 백도어를 만들어 놓거나, 설정 파일을 변경했을 때 분석하는 도구는?","choices":[{"n":1,"html":"trace"},{"n":2,"html":"tripwire"},{"n":3,"html":"udpdump"},{"n":4,"html":"cron"}],"answer":[2],"wiki":[{"title":"Tripwire","url":"https://itwiki.kr/w/Tripwire"}],"explain":{"ai":["<p>해킹으로 인해 시스템에 침입한 크래커가 백도어를 만들어 놓거나 설정 파일을 변경했을 때 시스템의 무결성을 분석하고 확인하는 데 사용하는 도구는 트립와이어이다. 트립와이어는 시스템 파일과 설정 파일의 일관성을 점검하여 변조 여부를 분석하고 보고하는 도구로, 시스템의 무결성을 유지하기 위해 사용된다. 침입검출과 방지를 위한 다양한 보안 도구 중 하나로, 시스템 파일과 디렉토리의 무결성을 확인하고 외부 침입으로 인한 변조를 탐지하는데 사용된다.</p>"]},"rate":68,"rateN":17660},{"id":"10673","number":88,"category":"정보시스템 구축관리","type":"choice","subject":"소프트웨어 개발 프레임워크를 적용할 경우 기대효과로 거리가 먼 것은?","choices":[{"n":1,"html":"품질보증"},{"n":2,"html":"시스템 복잡도 증가"},{"n":3,"html":"개발 용이성"},{"n":4,"html":"변경 용이성"}],"answer":[2],"explain":{"ai":["<p>소프트웨어 개발 프레임워크를 적용하면 여러 가지 기대효과가 있습니다. 먼저 개발 속도와 품질을 높일 수 있어 개발 용이성과 품질보증에 도움이 됩니다. 또한 변경 용이성을 높여줘서 유지 보수가 쉽습니다. 하지만 시스템의 복잡도를 고려하면 프레임워크 적용은 복잡도를 증가시키는 것보다는 통일성과 일관성을 부여하여 복잡도를 감소시킨다고 볼 수 있습니다. 따라서 시스템 복잡도 증가가 가장 기대효과와 거리가 멈이라는 결론을 내릴 수 있습니다.</p>"]},"rate":93,"rateN":13464},{"id":"10674","number":89,"category":"정보시스템 구축관리","type":"choice","subject":"COCOMO model 중 기관 내부에서 개발된 중소 규모의 소프트웨어로 일괄 자료 처리나 과학기술 계산용, 비즈니스 자료 처리용으로 5만 라인 이하의 소프트웨어를 개발하는 유형은?","choices":[{"n":1,"html":"embeded"},{"n":2,"html":"organic"},{"n":3,"html":"semi-detached"},{"n":4,"html":"semi-embeded"}],"answer":[2],"wiki":[{"title":"COCOMO","url":"https://itwiki.kr/w/COCOMO"}],"explain":{"ai":["<p>ＣＯＣＯＭＯ 모델은 보헴이 제안한 소프트웨어 개발 비용 및 개발 기간을 예측하는 모델이다. 이 모델은 개발 소프트웨어의 유형을 크게 3가지로 분류하며 그중 하나가 organic이다. \norganic 유형은 기관 내부에서 개발된 중소 규모의 소프트웨어를 개발하는 데 사용된다. 주로 일괄 자료 처리나 과학기술 계산용, 비즈니스 자료 처리용으로 5만 라인 이하의 소프트웨어 개발에 적합하다. \n따라서 중소 규모의 소프트웨어 개발 유형은 organic이 해당된다.</p>"]},"rate":62,"rateN":18939},{"id":"10675","number":90,"category":"정보시스템 구축관리","type":"choice","subject":"여러 개의 독립된 통신장치가 UWB(Ultra Wideband)기술 또는 블루투스 기술을 사용하여 통신망을 형성하는 무선 네트워크 기술은?","choices":[{"n":1,"html":"PICONET"},{"n":2,"html":"SCRUM"},{"n":3,"html":"NFC"},{"n":4,"html":"WI-SUN"}],"answer":[1],"explain":{"ai":["<p>전 세계적으로 다양한 기기들이 무선으로 통신할 수 있는 기술이운데 여러 개의 독립된 통신장치가 UWB 기술 또는 블루투스 기술을 사용하여 통신망을 형성하는 기술은 piconet이라고 합니다. 이를 사용하면 기기와 기기들이 물리적으로 근접거리에 위치하면 자동으로 네트워크를 형성하여 데이터를 주고받을 수 있습니다. 이러한 개인 지역 통신망은 장애물에 영향을 받지 않고 안정적으로 데이터를 전송할 수 있는 장점이 있습니다. 따라서 정답은 1번입니다.</p>"]},"rate":52,"rateN":22473},{"id":"10676","number":91,"category":"정보시스템 구축관리","type":"choice","subject":"프로토타입을 지속적으로 발전시켜 최종 소프트웨어 개발까지 이르는 개발방법으로 위험관리가 중심인 소프트웨어 생명주기 모형은?","choices":[{"n":1,"html":"나선형 모형"},{"n":2,"html":"델파이 모형"},{"n":3,"html":"폭포수 모형"},{"n":4,"html":"기능점수 모형"}],"answer":[1],"wiki":[{"title":"나선형_모델","url":"https://itwiki.kr/w/나선형_모델"}],"explain":{"ai":["<p><b>나선형 모형</b>은 프로토타입을 지속적으로 발전시켜 최종 소프트웨어 개발까지 이르는 개발방법으로, 위험관리가 중심입니다. 위험을 관리하고, 프로젝트의 안정성을 높이는 것을 목적으로 하며, 요구사항을 명확히 정의하기 어렵고, 프로젝트의 규모가 크거나 복잡한 경우에 적합합니다. 나선형 모형은 다음과 같은 단계로 구성됩니다.</p>\n<ul>\n<li> 계획 및 정의 </li>\n<li> 위험 분석 </li>\n<li> 설계 </li>\n<li> 구현 </li>\n<li> 테스트 </li>\n<li> 평가 및 유지보수 </li>\n</ul>\n위험을 중심으로 관리하며, 프로젝트의 각 단계에서 지속적으로 위험을 분석하고, 대응책을 마련합니다. 이러한 특징으로 인해 <b>나선형 모형</b>은 프로젝트의 성공을 높이고, 위험을 최소화하는 데 도움이 됩니다."]},"rate":75,"rateN":17231},{"id":"10677","number":92,"category":"정보시스템 구축관리","type":"choice","subject":"다음이 설명하는 용어로 옳은 것은?","extra":"<pre class=\"contents\">- 오픈 소스를 기반으로 한 분산 컴퓨팅 플랫폼이다.\r\n- 일반 PC급 컴퓨터들로 가상화된 대형 스토리지를 형성한다.\r\n- 다양한 소스를 통해 생성된 빅데이터를 효율적으로 저장하고 처리한다.</pre>","choices":[{"n":1,"html":"하둡(Hadoop)"},{"n":2,"html":"비컨(Beacon)"},{"n":3,"html":"포스퀘어(Foursquare)"},{"n":4,"html":"맴리스터(Memristor)"}],"answer":[1],"wiki":[{"title":"하둡","url":"https://itwiki.kr/w/하둡"}],"explain":{"ai":["<p>이 문제는 오픈 소스를 기반으로 한 분산 컴퓨팅 플랫폼에 대해 설명하고 있습니다. 이 플랫폼은 일반 PC급 컴퓨터들로 가상화된 대형 스토리지를 형성하며, 다양한 소스를 통해 생성된 빅데이터를 효율적으로 저장하고 처리합니다. 이러한 설명은 하둡(Hadoop)에 가장 잘 맞습니다. 하둡은 오픈 소스 기반의 분산 컴퓨팅 플랫폼으로, 빅데이터를 처리하기 위한 분산 파일 시스템과 맵 리듀스, mapreduce 프로그래밍 모델을 제공합니다. 따라서 정답은 1번 하둡(Hadoop)입니다.</p>"]},"rate":80,"rateN":15702},{"id":"10678","number":93,"category":"정보시스템 구축관리","type":"choice","subject":"소인수 분해 문제를 이용한 공개키 암호화 기법에 널리 사용되는 암호 알고리즘 기법은?","choices":[{"n":1,"html":"RSA"},{"n":2,"html":"ECC"},{"n":3,"html":"PKI"},{"n":4,"html":"PEM"}],"answer":[1],"wiki":[{"title":"타원 곡선 암호","url":"https://itwiki.kr/w/타원 곡선 암호"}],"explain":{"ai":["<p>정답은 1번 RSA입니다.</p>\n<p>RSA는 소인수 분해의 어려움을 기반으로 하는 대표적인 공개키 암호화 알고리즘입니다. 이 알고리즘의 핵심은 두 개의 큰 소수의 곱을 사용하는데, 이 곱을 다시 원래의 소수로 분해하는 것이 현대 컴퓨팅 기술로는 매우 어렵다는 사실에 있습니다.</p>\n<ul>\n<li><strong>RSA 작동 원리</strong>:<ul>\n<li><strong>키 생성</strong>: 두 개의 큰 소수 \\( p \\)와 \\( q \\)를 곱하여 \\( n = p \\times q \\)를 만듭니다. 이 \\( n \\)과 오일러 피 함수 \\( \\phi(n) = (p-1)(q-1) \\)를 이용해 공개키와 개인키를 생성합니다.</li>\n<li><strong>공개키</strong>: 주로 \\( (n, e) \\)로 표현되며, 여기서 \\( e \\)는 \\( \\phi(n) \\)과 서로소인 정수입니다.</li>\n<li><strong>개인키</strong>: 주로 \\( (n, d) \\)로, \\( d \\)는 \\( e \\times d \\equiv 1 \\mod \\phi(n) \\)을 만족하는 수입니다.</li>\n</ul>\n</li>\n</ul>\n<p>다른 옵션들에 대한 간략한 설명:</p>\n<ul>\n<li><strong>ECC (Elliptic Curve Cryptography)</strong>: 타원 곡선 암호화 기법으로, 더 짧은 키 길이로 높은 보안성을 제공하지만, 소인수 분해에 기반하지 않습니다.</li>\n<li><strong>PKI (Public Key Infrastructure)</strong>: 공개키 인프라 구조로, 공개키 암호화 기술을 관리하고 인증하는 시스템 체계입니다. 암호화 알고리즘 자체는 아닙니다.</li>\n<li><strong>PEM (Privacy Enhanced Mail)</strong>: 데이터를 암호화하고 인증서를 표현하는 파일 형식이지, 암호화 알고리즘이 아닙니다.</li>\n</ul>\n<p>따라서, 소인수 분해의 어려움을 핵심으로 하는 암호화 기법을 묻는 문제에서는 RSA가 정확한 답입니다.</p>"]},"rate":79,"rateN":15780},{"id":"10679","number":94,"category":"정보시스템 구축관리","type":"choice","subject":"LOC 기법에 의하여 예측된 총 라인수가 50000라인, 프로그래머의 월 평균 생산성이 200라인, 개발에 참여할 프로그래머가 10인 일 때, 개발 소요 기간은?","choices":[{"n":1,"html":"25개월"},{"n":2,"html":"50개월"},{"n":3,"html":"200개월"},{"n":4,"html":"2000개월"}],"answer":[1],"wiki":[{"title":"LOC","url":"https://itwiki.kr/w/LOC"}],"explain":{"ai":["<p>LOC 기법은 소프트웨어 개발에 필요한 총 라인수를 예측하여 개발 소요 기간과 필요한 인력을 계산하는 방법입니다. 총 라인수는 50000라인, 프로그래머의 월 평균 생산성은 200라인입니다. 개발에 참여할 프로그래머는 10명이며, 한 명의 프로그래머가 월 평균 200라인을 개발할 수 있기 때문에, 10명의 프로그래머는 월 평균 200 x 10 = 2000라인을 개발할 수 있습니다. </p>\n<p>따라서 개발 소요 기간은 총 라인수를 월 평균생산량으로 나눈값, 즉 50000 ÷ 2000 = 25개월이 됩니다. 따라서 정답은 25개월입니다.</p>"]},"rate":90,"rateN":13883},{"id":"10680","number":95,"category":"정보시스템 구축관리","type":"choice","subject":"최대 홉수를 15로 제한한 라우팅 프로토콜은?","choices":[{"n":1,"html":"RIP"},{"n":2,"html":"OSPF"},{"n":3,"html":"Static"},{"n":4,"html":"EIGRP"}],"answer":[1],"wiki":[{"title":"라우팅_프로토콜","url":"https://itwiki.kr/w/라우팅_프로토콜"}],"explain":{"ai":["<p>RIP(Routing Information Protocol)는 거리 벡터 라우팅 프로토콜로, 라우팅 업데이트 시 홉 수를 기준으로 경로를 평가한다. 이 프로토콜의 주요 특징 중 하나는 최대 홉 수 제한으로, 네트워크의 순환을 방지하고 계산 복잡도를 줄이기 위해 15홉을 최대치로 설정한다. 따라서 홉 수가 15를 넘는 네트워크는 도달 불가능한 것으로 간주된다. </p>\n<p>반면, OSPF는 링크 상태 프로토콜로 홉 수 제한이 없으며, 더 큰 네트워크에서 효율적으로 작동하도록 설계되었다. Static 라우팅은 관리자가 수동으로 경로를 설정하므로 홉 수 제한이 적용되지 않는다. EIGRP는 Cisco에서 개발한 프로토콜로, 내부적으로 복잡한 메트릭을 사용하여 경로를 결정하며, RIP와 달리 명시적인 홉 수 제한이 15로 고정되어 있지 않다.</p>\n<p>따라서 최대 홉 수를 15로 제한하는 프로토콜은 1번 RIP이다.</p>"]},"rate":71,"rateN":17026},{"id":"10681","number":96,"category":"정보시스템 구축관리","type":"choice","subject":"컴퓨터 사용자의 키보드 움직임을 탐지해 ID, 패스워드 등 개인의 중요한 정보를 몰래 빼가는 해킹 공격은?","choices":[{"n":1,"html":"Key Logger Attack"},{"n":2,"html":"Worm"},{"n":3,"html":"Rollback"},{"n":4,"html":"Zombie Worm"}],"answer":[1],"wiki":[{"title":"키로거","url":"https://itwiki.kr/w/키로거"}],"explain":{"ai":["<p>컴퓨터 사용자의 키보드 움직임을 탐지해 중요한 정보를 몰래 빼가는 해킹 공격은 키 로거 공격이다. 키 로거 공격은 사용자가 입력하는 모든 키보드 움직임을 기록하여 중요한 정보를 착취하는 방식으로 이루어진다. 따라서 키 로거 공격은 개인의 민감한 정보를 보호하기 위해 주의가 필요하다. 키 로거 공격을 방지하기 위해선 보안 프로그램을 설치하고 정기적으로 업데이트 하는 것이 중요하다. 또한ttps와 같은 보안 프로토콜을 사용하는 웹사이트에서 개인 정보를 입력할 때 주의해야 한다.</p>"]},"rate":91,"rateN":14093},{"id":"10682","number":97,"category":"정보시스템 구축관리","type":"choice","subject":"테일러링(Tailoring) 개발 방법론의 내부 기준에 해당하지 않는 것은?","choices":[{"n":1,"html":"납기/비용"},{"n":2,"html":"기술환경"},{"n":3,"html":"구성원 능력"},{"n":4,"html":"국제표준 품질기준"}],"answer":[4],"wiki":[{"title":"테일러링","url":"https://itwiki.kr/w/테일러링"}],"explain":{"ai":["<p>테일러링 개발 방법론은 프로젝트의 특성과 요구 사항에 따라개발 방법론을 조정하는 것을 말합니다. 내부 기준이란 프로젝트 내부의 요소를 말합니다. \n조직의 특성과 프로젝트 팀의 능력, 기술 환경이 프로젝트 개발 방법론을 제정할 때 주요한 내부 기준입니다. \n국제표준 품질 기준은 외부 기준에 해당합니다. 외부 기준이란 프로젝트 외부의 요인을 말하며, 국제표준이나 규정들이 포함되어 있습니다. \n따라서 테일러링 개발 방법론의 내부 기준에 해당하지 않는 것은 국제표준 품질기준입니다.</p>"]},"rate":55,"rateN":21112},{"id":"10683","number":98,"category":"정보시스템 구축관리","type":"choice","subject":"폭포수 모형의 특징으로 거리가 먼 것은","choices":[{"n":1,"html":"개발 중 발생한 요구사항을 쉽게 반영할 수 있다."},{"n":2,"html":"순차적인 접근방법을 이용한다."},{"n":3,"html":"단계적 정의와 산출물이 명확하다."},{"n":4,"html":"모형의 적용 경험과 성공사례가 많다."}],"answer":[1],"wiki":[{"title":"폭포수_모델","url":"https://itwiki.kr/w/폭포수_모델"}],"explain":{"ai":["<p>폭포수 모형은 정보시스템의 개발 단계를 순차적으로 진행하는 방법론이다. 이것은 개발 단계를 명확하게 정의하고 각 단계의 산출물이 확실하게 규정되어 있다. 또한 폭포수 모형은 개발 프로세스를 순차적으로 진행하며, 이전 단계가 완료되어야 다음 단계로 넘어갈 수 있다. </p>\n<p>이러한 특성으로 인해 폭포수 모형은 개발 중 발생한 요구사항을 쉽게 반영하기 어렵다. 한번 정의된 단계를 다시 변경하는 것은 어려울 수 있으며, 각 단계의 산출물이 명확히 정의되어 있기 때문에 요구사항의 변경이 어려울 수 있다. </p>\n<p>따라서 폭포수 모형의 특징으로 거리가 먼 것은 개발 중 발생한 요구사항을 쉽게 반영할 수 있다라는 것이다. 이것은 실제로 폭포수 모형의 약점 중 하나로 꼽히며, 최근에는 더 유연한 개발 방법론들로 대체되는 경우가 많다.</p>"]},"rate":83,"rateN":15377},{"id":"10684","number":99,"category":"정보시스템 구축관리","type":"choice","subject":"다음 설명의 정보보안 침해 공격 관련 용어는?","extra":"<pre class=\"contents\">인터넷 사용자의 컴퓨터에 침입해 내부 문서 파일 등을 암호화해 사용자가 열지 못하게 하는 공격으로, 암호 해독용 프로그램의 전달을 조건으로 사용자에게 돈을 요구하기도 한다.</pre>","choices":[{"n":1,"html":"Smishing"},{"n":2,"html":"C-brain"},{"n":3,"html":"Trojan Horse"},{"n":4,"html":"Ransomware"}],"answer":[4],"wiki":[{"title":"랜섬웨어","url":"https://itwiki.kr/w/랜섬웨어"},{"title":"스미싱","url":"https://itwiki.kr/w/스미싱"},{"title":"트로이 목마","url":"https://itwiki.kr/w/트로이 목마"}],"explain":{"ai":["<p>해설은 다음과 같다. \n인터넷 사용자의 컴퓨터에 침입해 문서 파일 등을 암호화해 사용자가 열지 못하게 하는 공격은 랜섬웨어 공격이라고 한다. 랜섬웨어는 암호화 공격을 통해 사용자의 파일을 암호화한 후 해독 키를 제공받기 위해 돈을 요구한다. 이는 개인 사용자뿐만 아니라 기업을 대상으로도 행해지는 경우가 많다. 따라서 설명된 공격은 랜섬웨어에 해당한다.</p>"]},"rate":84,"rateN":14994},{"id":"10685","number":100,"category":"정보시스템 구축관리","type":"choice","subject":"시스템 내의 정보는 오직 인가된 사용자만 수정할 수 있는 보안 요소는?","choices":[{"n":1,"html":"기밀성"},{"n":2,"html":"부인방지"},{"n":3,"html":"가용성"},{"n":4,"html":"무결성"}],"answer":[4],"wiki":[{"title":"보안","url":"https://itwiki.kr/w/보안"}],"explain":{"ai":["<p>시스템 내 정보 수정 권한을 인가된 사용자에게만 제한하는 것은 데이터의 정확성과 신뢰성을 보장하는 데 중점을 둔다. 이는 정보가 변조나 무단 변경 없이 원래의 상태를 유지하도록 하는 개념과 관련이 있다.</p>\n<ul>\n<li>기밀성은 정보에 대한 접근을 제한하여 비인가자가 내용을 볼 수 없게 하는 것을 의미한다.</li>\n<li>부인방지는 거래나 행위에 대한 기록을 통해 나중에 이를 부인하는 것을 방지하는 것이다.</li>\n<li>가용성은 필요한 사용자가 필요한 시기에 정보에 접근하거나 시스템을 사용할 수 있도록 보장하는 것을 말한다.</li>\n<li>무결성은 정보의 정확성과 완전성을 유지하여, 오직 인가된 사용자만이 정보를 수정할 수 있게 함으로써 데이터의 변조를 방지한다.</li>\n</ul>\n<p>따라서, 주어진 조건에 가장 부합하는 보안 요소는 <strong>무결성</strong>으로, 정답은 4번이다.</p>"]},"rate":46,"rateN":26160}]};